window.ScripturaLexicons.BDAG_PART_0276 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-01\" data-source=\"BDAG\" data-search=\"παροξύνω verbo estimular; provocar; irritar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροξύνω</td><td>verbo</td><td>estimular; provocar; irritar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-02\" data-source=\"BDAG\" data-search=\"παροξυσμός, οῦ, ὁ substantivo masculino estímulo; contenda intensa; crise convulsiva BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροξυσμός, οῦ, ὁ</td><td>substantivo masculino</td><td>estímulo; contenda intensa; crise convulsiva</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-03\" data-source=\"BDAG\" data-search=\"παροράω verbo ignorar; não dar atenção; deixar passar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροράω</td><td>verbo</td><td>ignorar; não dar atenção; deixar passar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-04\" data-source=\"BDAG\" data-search=\"παροργίζω verbo irritar; provocar ira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροργίζω</td><td>verbo</td><td>irritar; provocar ira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-05\" data-source=\"BDAG\" data-search=\"παροργισμός, οῦ, ὁ substantivo masculino irritação intensa; cólera BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροργισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>irritação intensa; cólera</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-06\" data-source=\"BDAG\" data-search=\"παρορίζω verbo ultrapassar limites; transgredir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρορίζω</td><td>verbo</td><td>ultrapassar limites; transgredir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-07\" data-source=\"BDAG\" data-search=\"παροτρύνω verbo incitar; estimular; instigar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροτρύνω</td><td>verbo</td><td>incitar; estimular; instigar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-08\" data-source=\"BDAG\" data-search=\"παρουσία, ας, ἡ substantivo feminino presença; chegada; advento; vinda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρουσία, ας, ἡ</td><td>substantivo feminino</td><td>presença; chegada; advento; vinda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-09\" data-source=\"BDAG\" data-search=\"παροψίς, ίδος, ἡ substantivo feminino prato; travessa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παροψίς, ίδος, ἡ</td><td>substantivo feminino</td><td>prato; travessa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-10\" data-source=\"BDAG\" data-search=\"παρρησία, ας, ἡ substantivo feminino franqueza; publicidade; ousadia; confiança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρρησία, ας, ἡ</td><td>substantivo feminino</td><td>franqueza; publicidade; ousadia; confiança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-11\" data-source=\"BDAG\" data-search=\"παρρησιάζομαι verbo médio depoente falar com franqueza; agir corajosamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">παρρησιάζομαι</td><td>verbo médio depoente</td><td>falar com franqueza; agir corajosamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-12\" data-source=\"BDAG\" data-search=\"πᾶς, πᾶσα, πᾶν adjetivo, pronome e substantivado todo; cada; qualquer; todas as coisas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πᾶς, πᾶσα, πᾶν</td><td>adjetivo, pronome e substantivado</td><td>todo; cada; qualquer; todas as coisas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-13\" data-source=\"BDAG\" data-search=\"πάσχα, τό substantivo neutro indeclinável Páscoa; cordeiro pascal; refeição pascal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάσχα, τό</td><td>substantivo neutro indeclinável</td><td>Páscoa; cordeiro pascal; refeição pascal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-14\" data-source=\"BDAG\" data-search=\"πάσχω verbo experimentar; sofrer; padecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πάσχω</td><td>verbo</td><td>experimentar; sofrer; padecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-15\" data-source=\"BDAG\" data-search=\"Πάταρα, ων, τά topônimo neutro plural Pátara, cidade da Lícia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πάταρα, ων, τά</td><td>topônimo neutro plural</td><td>Pátara, cidade da Lícia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-16\" data-source=\"BDAG\" data-search=\"πατάσσω verbo golpear; ferir; matar; atingir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πατάσσω</td><td>verbo</td><td>golpear; ferir; matar; atingir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-17\" data-source=\"BDAG\" data-search=\"πατέω verbo pisar; calcar; pisotear; caminhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πατέω</td><td>verbo</td><td>pisar; calcar; pisotear; caminhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-18\" data-source=\"BDAG\" data-search=\"πατήρ, πατρός, ὁ substantivo masculino pai; ancestral; progenitor; Deus Pai BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πατήρ, πατρός, ὁ</td><td>substantivo masculino</td><td>pai; ancestral; progenitor; Deus Pai</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-19\" data-source=\"BDAG\" data-search=\"Πάτμος, ου, ὁ nome geográfico masculino Patmos, ilha do mar Egeu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πάτμος, ου, ὁ</td><td>nome geográfico masculino</td><td>Patmos, ilha do mar Egeu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0276-20\" data-source=\"BDAG\" data-search=\"πατραλῴας remissão ver πατρολῴας BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πατραλῴας</td><td>remissão</td><td>ver πατρολῴας</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0276-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροξύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροξύνω</span> (<span class=\"greek\">ὀξύνω</span> «afiar», depois «provocar»; veja o verbete seguinte), futuro, 3.ª pessoa singular <span class=\"greek\">παροξυνεῖ</span> LXX; aoristo <span class=\"greek\">παρώξυνα</span> LXX. Passivo: imperfeito <span class=\"greek\">παρωξυνόμην</span>; futuro, 3.ª pessoa singular <span class=\"greek\">παροξυνθήσεται</span> Da 11:10; aoristo, 3.ª pessoa singular <span class=\"greek\">παρωξύνθη</span> LXX (trágicos, Thu.; OGI 48, 15; BGU 588, 7; LXX; pseudoepígrafos; Mel., P. 93, 699), produzir um estado de excitação interior, impelir, estimular, especialmente provocar ira, irritar (Eur., Thu. e outros; LXX; PsSol 4:21; TestSim 4:8; TestAsh 2:6; GrBar 1:6; Philo, Joseph.; Mel., P. 93, 699); passivo, ficar irritado, irar-se (Thu. 6, 56, 2 e outros; M. Ant. 9, 42, 7; Arrian, Anab. 4, 4, 2; Sb 8852, 15 [III a.C.] <span class=\"greek\">παροξυνόμενοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">νεώτεροι</span>; Hos 8:5; Zech 10:3; TestDan 4:2; Jos., Bell. 2, 8, Ant. 7, 33); acerca do amor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:5</a>. <span class=\"greek\">παρωξύνετο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> «seu espírito se agitava dentro dele» (por ira, tristeza ou desejo de convertê-los) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:16</a> (veja Nock, Essays I 824, com referência a X., Cyr. 6, 2, 5; cf. MDibelius, Aufsätze zur Apostelgeschichte2 ’53, 61).—DELG s.v. <span class=\"greek\">ὀξύς</span>. M-M s.v. <span class=\"greek\">παροξύνομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροξυσμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροξυσμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">παρόξυνω</span>; Demosth. e outros; LXX).<br><br>① Estímulo à atividade, incitamento, provocação (assim o verbo <span class=\"greek\">παροξύνω</span> nas vozes ativa e passiva; X., Mem. 3, 3, 13 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">καλά</span>, Oec. 13, 9; Isocr., Ad Demonic. 46) <span class=\"greek\">εἰς</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἀγάπης</span> «para estímulo ao amor», isto é, para encorajar alguém no amor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:24</a>.<br><br>② Estado de irritação manifestado em discussão, desacordo acirrado («irritação, exasperação»: Demosth. 45, 14; Ael. Aristid. 37 p. 709 D.; 52 p. 600; Dt 29:27; Jer 39:37) <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">π</span>. «surgiu uma discussão acirrada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:39</a>.<br><br>③ Acesso grave de uma doença, crise febril, especialmente em seu ponto máximo: convulsão (Hippocr., Aph. 1, 11; 12; 2, 13; Galen XIII p. 210; Artem. 3, 56; PTebt 272, 6.—Hobart 233) IPol 2:1.—DELG s.v. <span class=\"greek\">ὀξύς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροράω</span>, futuro da 3.ª pessoa singular <span class=\"greek\">παρόψεται</span> Job 11:11; aoristo <span class=\"greek\">παρεῖδον</span>. Passivo: infinitivo futuro <span class=\"greek\">παροραθήσεσθαι</span> 2 Macc 3:9; perfeito da 3.ª pessoa singular <span class=\"greek\">παρῶπται</span> (Ath., R. 19 p. 71, 29), particípio <span class=\"greek\">παρεωράμενος</span> LXX (X., Pla.+), olhar apenas de passagem, ignorar, não dar atenção a (Aristot. e outros; BGU 1140, 23 [I a.C.]; Wsd 11:23 <span class=\"greek\">παρορᾷς</span> <span class=\"greek\">ἁμαρτήματα</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μετάνοιαν</span>; Philo, Rer. Div. Her. 109) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:30</a> D.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροργίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροργίζω</span>, futuro ático <span class=\"greek\">παροργιῶ</span> (mas 2.ª pessoa plural <span class=\"greek\">παροργίσετε</span> TestZeb 9:9); 1.º aoristo <span class=\"greek\">παρώργισα</span>. Passivo: futuro da 3.ª pessoa singular <span class=\"greek\">παροργισθήσεται</span> Da 11:36; particípio perfeito, acusativo feminino <span class=\"greek\">παρωργισμένην</span> Sir 4:3; tornar irado (assim no passivo em Theophr., HP 9, 16, 6; Strabo 7, 2, 1; OGI 610, 4 [VI d.C.]), <span class=\"greek\">τινά</span> «alguém» (LXX; TestJob 43:9; Test12Patr; GrBar 16:2; TestLevi 3:10 [leitura fracamente atestada]; Philo, Somn. 2, 177; Just., D. 130, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:19</a> (Dt 32:21); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:4</a> (cf. Pla., Leg. 7, 823cd acerca de uma educação eficaz pelo louvor em vez de ameaças); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:21</a>, variante textual; Hv 3, 6, 1.—DELG s.v. 1 <span class=\"greek\">ὀργή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροργισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροργισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (PsSol 8:9; LXX, principalmente em sentido ativo, «provocação à ira»: 3 Km 15:30; 4 Km 23:26, ou «ato que desperta a ira» em alguém: 2 Esdr 19:18), estado de intensa provocação, disposição irada, ira, em sentido passivo (Jer 21:5 com <span class=\"greek\">θυμός</span> e <span class=\"greek\">ὀργή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:26</a> (cf. dito pitagórico em Plut., Mor. 488bc; também 1QS 5:26–6:1; CD 9:6–8).—DELG s.v. <span class=\"greek\">ὀργή</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρορίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρορίζω</span>, ir além de um limite ou fronteira, ultrapassar, transgredir (assim Ammianus Epigr. [II d.C.]: Anth. Pal. 11, 209, 1; Anecd. Gr. p. 293, 16. No sentido de «deslocar um marco divisório», IPriene 37, 142 [II a.C.]; BGU 616, 4; PTebt 410, 5 [I d.C.]); passivo, <span class=\"greek\">οἷς</span> (por quem) <span class=\"greek\">ὅρια</span> <span class=\"greek\">παρορίζεται</span> «limites são transgredidos» Dg 11:5.—DELG s.v. <span class=\"greek\">ὅρος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροτρύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροτρύνω</span> (<span class=\"greek\">ὀτρύνω</span> «incitar»), 1.º aoristo <span class=\"greek\">παρώτρυνα</span>, despertar forte emoção contra alguém, estimular, incitar <span class=\"greek\">τινά</span> «alguém» (Pind., O. 3, 38 em manuscritos tardios [veja BGildersleeve, Pindar ’85, 161 e ABoeckh sobre a passagem]; Lucian, Tox. 35, Deor. Concil. 4; Ael. Aristid. 53 p. 633 D.; Jos., Ant. 7, 118) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.50\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:50</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρουσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρουσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πάρειμι</span>; trágicos, Thu.+).<br><br>① Estado de estar presente em algum lugar, presença (Aeschyl. e outros; Herm. Wr. 1, 22; OGI 640, 7, SIG 730, 14; Did.; cf. Hippol., Ref. 7, 32, 8 «existência») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:12</a> (oposto a <span class=\"greek\">ἀπουσία</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> <span class=\"greek\">ἀσθενής</span> «sua presença corporal é fraca», isto é, quando está pessoalmente presente, aparenta fraqueza, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:10</a>.—A respeito de Deus (Jos., Ant. 3, 80; 203; 9, 55), <span class=\"greek\">τῆς</span> <span class=\"greek\">παρουσίας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">δείγματα</span> «provas de sua presença» Dg 7:9 (cf. Diod S 3, 66, 3 <span class=\"greek\">σημεῖα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παρουσίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; 4, 24, 1).<br><br>② Chegada como primeira etapa de uma presença, vinda, advento (Soph., El. 1104; Eur., Alc. 209; Thu. 1, 128, 5. Em outros lugares, sobretudo em autores posteriores: Polyb. 22, 10, 14; Demetr.: 722 Fgm. 11, 18 Jac.; Diod S 15, 32, 2; 19, 64, 6; Dionys. Hal. 1, 45, 4; inscrições, papiros; Jdth 10:18; 2 Macc 8:12; 15:21; 3 Macc 3:17; TestAbr A 2 p. 78, 26 [Stone p. 4]; Jos., Bell. 4, 345, Vi. 90; Tat. 39, 3).<br><br>ⓐ Acerca de seres humanos, no sentido habitual, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:6f</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> <span class=\"greek\">π</span>. <span class=\"greek\">πάλιν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> «minha nova vinda até vós, meu retorno a vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:26</a>.—RFunk, Festschrift JKnox ’67, 249–68.<br><br>ⓑ Em sentido técnico especial (diferentemente JWalvoord, BiblSacr 101, ’44, 283–89 acerca de <span class=\"greek\">παρ</span>., <span class=\"greek\">ἀποκάλυψις</span>, <span class=\"greek\">ἐπιφάνεια</span>), acerca de Cristo (e do Anticristo). O emprego de <span class=\"greek\">π</span>. como termo técnico desenvolveu-se em duas direções. Por um lado, a palavra servia de expressão sagrada para a vinda de uma divindade oculta, que manifesta sua presença mediante revelação de seu poder, ou cuja presença se celebra no culto (Diod S 3, 65, 1 <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">π</span>. acerca de Dioniso na terra; 4, 3, 3; Ael. Aristid. 48, 30; 31 K.=24 p. 473 D.; Porphyr., Philos. Ex Orac. Haur. II p. 148 Wolff; Iambl., Myst. 2, 8; 3, 11; 5, 21; Jos., Ant. 3, 80; 203; 9, 55; relato de cura de Epidauro: SIG 1169, 34).—Por outro lado, <span class=\"greek\">π</span>. tornou-se termo oficial para a visita de uma pessoa de alta posição, especialmente reis e imperadores visitando uma província (Polyb. 18, 48, 4; CIG 4896, 8f; SIG 495, 85f; 741, 21; 30; UPZ 42, 18 [162 a.C.]; PTebt 48, 14; 116, 57 [ambos II a.C.]; O. Wilck II, 1372; 1481. Sobre o verbo nesse sentido, veja BGU XIII, 2211, 5.—O. Wilck I 274ff; Dssm., LO 314ff [LAE 372ff]; MDibelius, Hdb., excurso após a explicação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:20</a>). Essas duas expressões técnicas podem aproximar-se bastante em significado, fundir seus matizes ou mesmo coincidir (inscrição de Tegeia: BCH 25, 1901 p. 275 <span class=\"greek\">ἔτους</span> <span class=\"greek\">ξθ</span>´ <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">Ἁδριανοῦ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">ἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ελλάδα</span> <span class=\"greek\">παρουσίας</span>).—Herm. Wr. 1, 26 emprega <span class=\"greek\">π</span>. acerca da chegada do peregrino à oitava esfera.<br><br><span class=\"greek\">α</span>. Acerca de Cristo, e quase sempre de seu advento messiânico em glória para julgar o mundo no fim da presente era: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:3</a> (PSchoonheim, Een semasiolog. onderzoek van <span class=\"greek\">π</span>. ’53); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:8</a>, variante textual; 15:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:8</a> (sobre a expressão <span class=\"greek\">ἐπιφάνεια</span> <span class=\"greek\">παρουσίας</span>, veja FPfister, Pauly-W. Suppl. IV ’24, 322); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:28</a>; Dg 7:6; Hs 5, 5, 3. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπου</span> «a vinda do Filho do Homem» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:27</a>, 37, 39 (cf. sugestão de retribuição em SIG 741, 21–23; 31f). <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> «a vinda do Senhor» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7f</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> «a vinda de nosso Senhor Jesus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:13</a>; cf. 2:19. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> «a vinda de nosso Senhor Jesus Cristo» 5:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:1</a> (sobre o uso em 1 e 2 Th, veja RGundry, NTS 33, ’87, 161–78); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:16</a> (<span class=\"greek\">δύναμις</span> com <span class=\"greek\">παρουσία</span> como Jos., Ant. 9, 55; cf. Ael. Aristid. 48, 30 K. [ambas as passagens também em b acima]).—Isso explica a expressão <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡμέρας</span> «a vinda do Dia de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:12</a>.—EvDobschütz, Zur Eschatologie der Ev.: StKr 84, 1911, 1–20; FTillmann, D. Wiederkunft Christi nach den paulin. Briefen 1909; FGuntermann, D. Eschatol. des hl. Pls ’32; BBrinkmann, D. Lehre v. d. Parusie b. hl. Pls u. im Hen.: Biblica 13, ’32, 315–34; 418–34; EHaack, E. exeg.-dogm. Studie z. Eschatol. über <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:13</a>–18: ZST 15, ’38, 544–69; OCullmann, Le retour de Christ2 ’45; WKümmel, Verheissg. u. Erfüllg.2 ’53; TGlasson, The Second Advent ’45; AFeuillet, Festschrift CHDodd ’56 (Mt e Js).—Sobre a demora da parusia, WMichaelis, Festschrift Wikenhauser ’53, 107–23; EGrässer, D. Problem der Parousieverzögerung (sinóticos e Atos), ’57.—JATRobinson, Jesus and His Coming, ’57.<br><br><span class=\"greek\">β</span>. Em nossa literatura, provavelmente apenas em poucas passagens tardias, acerca do advento de Jesus na encarnação (assim TestLevi 8:15; TestJud 22:2; Just., A I, 52, 3, D. 14, 8; 40, 4; 118, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">παρουσίᾳ</span>; Ps.-Clem., Hom. 2, 52; 8, 5; Orig., C. Cels. 6, 68, 5; Hippol., Ref. 9, 30, 5) <span class=\"greek\">τὴν</span> <span class=\"greek\">παρουσίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωτῆρος</span>, <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀνάστασιν</span> IPhld 9:2; PtK 4 p. 15, 33. Mas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:16</a> (veja <span class=\"greek\">α</span> acima) dificilmente pode ser classificado aqui.<br><br><span class=\"greek\">γ</span>. A acepção <span class=\"greek\">α</span> deu origem a um uso oposto de <span class=\"greek\">π</span>. para designar a vinda do Anticristo (veja <span class=\"greek\">ἄνομος</span> 4; Iren. 3, 7, 2 [Harv. II 26f]; Orig., C. Cels. 6, 45, 5) nos últimos tempos, <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐνέργειαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> «cuja vinda ocorre conforme o poder de Satanás» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:9</a>. KThraede, Grundzüge griechisch-römischer Brieftopik ’70, 95–106.—New Docs 4, 167f. DELG s.v. <span class=\"greek\">εἰμί</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παροψίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παροψίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὄψον</span> «alimento preparado»; desde Magnes Com. [V a.C.] 2; Pherecrates Com. [V a.C.] 147; X., Cyr. 1, 3, 4, no sentido de «acompanhamento» [comida]), prato, travessa (= recipiente. Antiphanes e outros; Plut., Mor. 828a; Epict. 2, 20, 30; Artem. 1, 74 p. 67, 6; Alciphron 2, 17, 3; BGU 781, 2; 6; 14 [I d.C.]. Os aticistas rejeitavam o emprego da palavra nesse sentido transferido: Phryn. p. 176 Lob.; Moeris p. 297 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:25</a>, 26, variante textual.—DELG s.v. <span class=\"greek\">ὄψον</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρρησία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πᾶς</span>, <span class=\"greek\">ῥῆσις</span>; Eur., Pla.+; Stob., Flor. III 13 p. 453 H. [coleção de ditos <span class=\"greek\">περὶ</span> <span class=\"greek\">παρρησίας</span>]; inscrições, papiros, LXX; TestReub 4:2; JosAs 23:10 cód. A [Bat. p. 75, 2] e Pal. 364; EpArist, Philo, Joseph.; Ath. 11, 2; empréstimo no uso rabínico.—Sobre a grafia, veja B-D-F §11, 1; Mlt-H. 101; veja também Schwyzer I 469).<br><br>① Uso da fala que não esconde nem omite coisa alguma, franqueza, sinceridade, clareza (Demosth. 6, 31 <span class=\"greek\">τἀληθῆ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">ἐρῶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἀποκρύψομαι</span>; Diod S 4, 74, 2; 12, 63, 2; Pr 1:20; um escravo não dispõe de tal privilégio: Eur., Phoen. 390–92) <span class=\"greek\">παρρησίᾳ</span> «claramente, abertamente» (EpArist 125) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:13</a>; 10:24; 11:14; 16:25 (oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">παροιμίαις</span>.—Sobre o assunto, cf. Artem. 4, 71 <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοὶ</span> <span class=\"greek\">πάντως</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἀληθῆ</span> <span class=\"greek\">λέγουσιν</span>, <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ποτὲ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἁπλῶς</span> <span class=\"greek\">λέγουσι</span>, <span class=\"greek\">ποτὲ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">αἰνίσσονται</span> = «os deuses dizem sempre a verdade, mas às vezes diretamente, às vezes de forma indireta»), 29, variante textual (oposto a <span class=\"greek\">παροιμία</span>); Dg 11:2. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:29</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> (veja Demosth. acima; Ael. Aristid. 30 p. 571 D.; Appian, Bell. Civ. 3, §15 <span class=\"greek\">λέγω</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">π</span>.; 3 Macc 4:1; 7:12; JosAs 23:10 [veja acima]; Philo; Jos., Ant 6, 256) «abertamente, com confiança» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:29</a>; <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">ἄκουε</span> «ouve com franqueza» MPol 10:1. Também aqui cabe <span class=\"greek\">πολλῇ</span> <span class=\"greek\">παρρησίᾳ</span> <span class=\"greek\">χρώμεθα</span> (em oposição ao véu no rosto de Moisés) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:12</a> (<span class=\"greek\">παρρησίᾳ</span> <span class=\"greek\">χράομαι</span> como Appian, Maced. 11 §3; Cass. Dio 62, 13; Philo, De Jos. 107; Jos., Ant. 2, 116).—RPope, ET 21, 1910, 236–38; HWindisch, excurso sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:12</a>.<br><br>② «Abertura» às vezes desenvolve o sentido de publicidade, diante do público, perante o qual se dão a fala e as ações (Philo, Spec. Leg. 1, 321 <span class=\"greek\">τοῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κοινωφελῆ</span> <span class=\"greek\">δρῶσιν</span> <span class=\"greek\">ἔστω</span> <span class=\"greek\">παρρησία</span>) <span class=\"greek\">παρρησίᾳ</span> «em público, publicamente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:26</a>; 11:54; 18:20. <span class=\"greek\">δειγματίζειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> «expor publicamente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:15</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> <span class=\"greek\">εἶναι</span> «ser conhecido publicamente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:4</a> (oposto a <span class=\"greek\">ἐν</span> <span class=\"greek\">κρυπτῷ</span>). Provavelmente também aqui cabe <span class=\"greek\">παρρησίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:19</a>, variante textual, e <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">ἀκωλύτως</span> «inteiramente às claras e sem impedimento» 28:31. Também <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">παρρησίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>. Provavelmente também pertence aqui <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4</a> (mas alguns preferem o sentido 3): «falo-vos com muita franqueza» (REB; isto é, sem pesar cada palavra).<br><br>③ Estado de ousadia e confiança, coragem, confiança, intrepidez, especialmente diante de pessoas de posição elevada.<br><br>ⓐ Na relação com seres humanos (Socrat., Ep. 1, 12; Cass. Dio 62, 13; EpArist 125 <span class=\"greek\">παρρησίᾳ</span>; Philo, De Jos. 107; 222, Rer. Div. Her. 5f; Jos., Ant. 9, 226; 15, 37; TestReub 4:2f. Cf. também OGI 323, 10; POxy 1100, 15; PGM 12, 187; OEger, Rechtsgeschichtliches zum NT: Rektoratsprogr. Basel 1919, 41f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:13</a>. Alguns situariam aqui <span class=\"greek\">πολλή</span> <span class=\"greek\">μοι</span> <span class=\"greek\">παρρησία</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> (subentendido <span class=\"greek\">ἐστίν</span> e cf. Diod S 14, 65, 4 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τύραννον</span> <span class=\"greek\">π</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:4</a>, mas o contexto parece favorecer a acepção 2 acima. <span class=\"greek\">πολλὴν</span> <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">ἐπιτάσσειν</span> <span class=\"greek\">σοι</span> Phlm 8 (<span class=\"greek\">π</span>. <span class=\"greek\">ἔχω</span> como Dio Chrys. 26 [43], 7). <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> «destemidamente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:19</a> (DSmolders, L’audace de l’apôtre: Collectanea Mechlinensia 43, ’58, 16–30; 117–33; RWild, CBQ 46, ’84, 284–98; o verbo com <span class=\"greek\">ἅλυσις</span> no v. 20; cf. a situação de Paulo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:30f</a>). <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> (Aristoxenus, Fgm. 32; Appian, Bell. Civ. 5, 42 §178; Jos., Ant. 6, 256; Ps.-Clem., Hom. 1, 11; 5, 18; <span class=\"greek\">μετὰ</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">κρύβδην</span> Orig., C. Cels. 3, 57, 20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:29</a> (cf. Chion 16, 7 H. <span class=\"greek\">ἀνέξῃ</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">μοῦ</span> <span class=\"greek\">λέγοντος</span>); 4:31; 1 Cl 34:1. <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">πάσης</span> (Jos., Ant. 16, 379) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:29</a>; 6:10 D; 16:4 D.<br><br>ⓑ Na relação com Deus (Job 27:10; Philo, Rer. Div. Her. 5–7; Jos., Ant. 5, 38), com <span class=\"greek\">προσαγωγή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:12</a>. Aqui, alegria e confiança são resultado ou acompanhamento da fé, como em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.35\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:35</a>. Com <span class=\"greek\">καύχημα</span> 3:6; 1 Cl 34:5. <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> (Jos., Ant. 2, 52) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:21</a>; cf. 5:14. <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> «com coração jubiloso» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:16</a>; 2 Cl 15:3. <span class=\"greek\">ἀλήθεια</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">παρρησίᾳ</span> 1 Cl 35:2. <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἴσοδον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> «visto que temos confiança para entrar no santuário» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:19</a>.—Com coloração expressamente forense e escatológica (como Wsd 5:1), <span class=\"greek\">παρρησίαν</span> <span class=\"greek\">ἔχειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:28</a> (oposto a <span class=\"greek\">αἰσχύνεσθαι</span>); 4:17.—EPeterson, Z. Bedeutungsgesch. v. <span class=\"greek\">π</span>.: Festschrift RSeeberg I 1929, 283–97; WvUnnik, The Christian’s Freedom of Speech: BJRL ’62, 466–88; HCombrink, Parresia in Handelinge: GereformTT ’75, 56–63; WBeilner, <span class=\"greek\">ΠΑΡΡΗΣΙΑ</span> ’79 (bibliografia); SMarrow, CBQ 44, ’82, 431–46; PMiguel, Parrhēsia: Dictionnaire de spiritualité 12, ’83, 260–67; também artigos de DFredrickson, SWinter, AMitchell, WKlassen, em Friendship, Flattery, and Frankness of Speech ’96, 163–254; RAC VII 839–77.—DELG s.v. 2 <span class=\"greek\">εἴρω</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">παρρησιάζομαι</h1><div class=\"entry-meta\"><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">παρρησιάζομαι</span> (<span class=\"greek\">παρρησία</span>), médio depoente (Pla. e outros; LXX, Philo), imperfeito <span class=\"greek\">ἐπαρρησιαζόμην</span>; futuro <span class=\"greek\">παρρησιάσομαι</span> e médio-passivo, 2.ª pessoa singular <span class=\"greek\">παρρησιασθήσῃ</span> Job 22:26; 1.º aoristo <span class=\"greek\">ἐπαρρησιασάμην</span> (sobre o aumento, veja B-D-F §69, 4; Mlt-H. 192, n. 3), infinitivo médio-passivo <span class=\"greek\">παρρησιασθῆναι</span> GrBar 9:8.<br><br>① Expressar-se livremente, falar com liberdade, abertamente, sem temor, absolutamente (X., Ages. 11, 5; Aeschines 1, 172; 2, 70; Diod S 14, 7, 6; Jos., Ant. 16, 377) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:26</a>; 19:8; igualmente, em particípio seguido de verbo de dizer (Appian, Bell. Civ. 1, 56 §247 <span class=\"greek\">παρρησιαζόμενον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέγοντα</span>), <span class=\"greek\">παρρησιασάμεοι</span> <span class=\"greek\">εἶπαν</span> 13:46.—26:26. <span class=\"greek\">π</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> «falar livremente a alguém ou com alguém» (X., Cyr. 5, 3, 8; Diod S 23, 12, 1; Lucian, Ind. 30. Cf. <span class=\"greek\">π</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Ἰουδαίων</span> Orig., C. Cels. 2, 45, 11) 1 Cl 53:5. Com <span class=\"greek\">ἐν</span> indica-se a razão da <span class=\"greek\">παρρησία</span> e, simultaneamente, o objeto da fala livre: <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">Ἰησοῦ</span> «falar abertamente no nome de Jesus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:27</a>; cf. v. 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:20</a>. Igualmente com <span class=\"greek\">ἐπί</span> e dativo (Phalaris, Ep. 139 <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">π</span>.—B-D-F §235, 2), <span class=\"greek\">π</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:3</a>.<br><br>② Quando acompanhado do infinitivo, <span class=\"greek\">π</span>. adquire (por analogia com <span class=\"greek\">τολμᾶν</span>, veja B-D-F §392, 3) o sentido de ter coragem, ousar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:2</a> (assim com o particípio, Ps.-Clem., Hom. 4, 17).<br><br>③ A citação de Ps 11:6, <span class=\"greek\">παρρησιάσομαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, é peculiar, significando aproximadamente «tratá-lo-ei com franqueza (ousadia)» 1 Cl 15:7.—DELG s.v. <span class=\"greek\">εἴρω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πᾶς, πᾶσα, πᾶν</h1><div class=\"entry-meta\"><span>adjetivo, pronome e substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πᾶς</span>, <span class=\"greek\">πᾶσα</span>, <span class=\"greek\">πᾶν</span>, genitivo <span class=\"greek\">παντός</span>, <span class=\"greek\">πάσης</span>, <span class=\"greek\">παντός</span> (as formas do dativo plural <span class=\"greek\">πᾶσι</span> e <span class=\"greek\">πᾶσιν</span> variam consideravelmente nos manuscritos; veja W-S. §5, 28; cf. Rob. 219–21; sobre o uso do artigo, veja B-D-F §275) (Hom.+).<br><br>① Relativo à totalidade, com ênfase nos seus componentes individuais, cada, todo, qualquer.<br><br>ⓐ Como adjetivo, empregado com substantivo sem artigo.<br><br><span class=\"greek\">α</span>. No singular, ressaltando os membros individuais da classe designada pelo substantivo, «todo, cada, qualquer», com significado pouco diferente daquele do plural «todos»: <span class=\"greek\">πᾶν</span> <span class=\"greek\">δένδρον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φυτεία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:13</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">φάραγξ</span>, <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὄρος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4). <span class=\"greek\">πᾶς</span> <span class=\"greek\">τόπος</span> 4:37. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:9</a>; 2:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:4</a> (Ps 115:2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:28abd</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:19</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">γυνή</span> GJs 11:2. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἔθνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:26a</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ψυχή</span> (Pla., Phdr. 249e) 2:43; 3:23 (cf. Lev 23:29); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:9</a>; Jd 15. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡμέρα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:42</a>; 17:17. <span class=\"greek\">πᾶν</span> <span class=\"greek\">σάββατον</span> 18:4. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἐξουσία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a> (cf. Just., D. 111, 2 <span class=\"greek\">οὗ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">δέδιεν</span>). <span class=\"greek\">πᾶσα</span> <span class=\"greek\">συνείδησις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἅγιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:21</a>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">οἶκος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:4</a> (GJs 7:3). <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἀντιλογία</span> 7:7. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">παιδεία</span> «toda disciplina» 12:11. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὀφθαλμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7a</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">κτίσμα</span> 5:13a.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23</a> (Ex 13:2); 4:13; 21:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a> (Da 11:36). <span class=\"greek\">πᾶσα</span> <span class=\"greek\">κτίσις</span> «toda criatura» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:15</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">κτίσει</span> «a toda criatura» v. 23. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">γραφή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:16</a> (veja <span class=\"greek\">γραφή</span> 2a).—<span class=\"greek\">πᾶσα</span> <span class=\"greek\">σάρξ</span> (<span class=\"hebrew\" dir=\"rtl\">כָּל־בָּשָׂר</span>; usado no AT, também En 1:9; TestGad 7:2; GrBar 4:10; mas não em EpArist, Philo nem Joseph.) «toda carne» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:6</a> (Is 40:5); AcPlCor 2:6 e 16 (veja também 3b abaixo). Principalmente com negação (assim também En 14:21; 17:6), <span class=\"greek\">οὐ</span> (ou <span class=\"greek\">μή</span>) … <span class=\"greek\">πᾶσα</span> <span class=\"greek\">σάρξ</span> «nenhuma carne = ninguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:16</a> (cf. GrBar 8:7 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἐσώθη</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">πνοή</span>). Outras expressões negativas semelhantes também são hebraísmos (veja B-D-F §302, 1; Mlt-H. 433f), <span class=\"greek\">οὐ</span> … <span class=\"greek\">πᾶν</span> <span class=\"greek\">ῥῆμα</span> «nem uma coisa sequer, nada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:37</a> (cf. PRyl 113, 12f [133 d.C.] <span class=\"greek\">μὴ</span> … <span class=\"greek\">πᾶν</span> <span class=\"greek\">πρᾶγμα</span>). <span class=\"greek\">οὐδέποτε</span> <span class=\"greek\">ἔφαγον</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">κοινόν</span> «nunca comi coisa alguma comum» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:14</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:1</a>, 16; 9:4; 21:27. Também na ordem inversa, <span class=\"greek\">πᾶς</span> … <span class=\"greek\">οὐ</span> ou <span class=\"greek\">μή</span> (Ex 12:16; Sir 8:19; 10:6, mas veja também GLee, ET 63, ’51f, 156) 18:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:29</a>; 5:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:21</a>; 3:15b.—Somente raramente se emprega um particípio com <span class=\"greek\">πᾶς</span> desta maneira: <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀκούοντος</span> «quando qualquer um ouve» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:19</a>. <span class=\"greek\">παντὶ</span> <span class=\"greek\">ὀφείλοντι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:4</a> (Mlt-Turner 196f).<br><br><span class=\"greek\">β</span>. Com substantivo no plural, sem artigo, <span class=\"greek\">πάντες</span> <span class=\"greek\">ἄνθρωποι</span> «todas as pessoas, todos» (Lysias 12, 60; Andoc. 3, 25; X., Cyr. 7, 5, 52, Mem. 4, 4, 19; Demosth. 8, 5; 18, 72) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12a</a>, 18ab; 12:17, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:7</a>; 15:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:4</a>; 4:10; Tit 2:11. <span class=\"greek\">πάντες</span> <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">θεοῦ</span> «todos os anjos de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:6</a> (Dt 32:43; cf. Demosth. 18, 294 <span class=\"greek\">πάντες</span> <span class=\"greek\">θεοί</span>).<br><br>ⓑ Adjetivo empregado com substantivo ou particípio acompanhado do artigo.<br><br><span class=\"greek\">α</span>. No singular. Frequentemente <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span>, <span class=\"greek\">πάσα</span> <span class=\"greek\">ἡ</span>, <span class=\"greek\">πᾶν</span> <span class=\"greek\">τό</span> é empregado com particípio (B-D-F §413, 2 e 3), «cada um que, todo aquele que, quem quer que»: <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> (Soph., Aj. 152; Demosth. 23, 97; Sir 22:2, 26; 1 Macc 1:52; 2:27) <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀργιζόμενος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a>. Cf. vv. 28, 32; 7:8, 26 (=<span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅστις</span> v. 24; veja abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:47</a>; 11:10; 14:11; 16:18; 18:14; 19:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:8</a>, 15f, 20; 4:13; 6:40; 8:34; 18:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:43b</a>; 13:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:1</a>, 10; 10:4, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:23</a>, 29 e outros; 2J 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:18</a>.—<span class=\"greek\">πᾶν</span> <span class=\"greek\">τό</span> «tudo aquilo que» (1 Macc 10:41): <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἰσπορευόμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:18</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀφειλόμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:34</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πωλούμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:25</a>; cf. v. 27. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φανερούμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:14</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γεγεννημένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4</a>.—Equivalente desta expressão é <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὅς</span> (ou <span class=\"greek\">ὅστις</span>), <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὅ</span> «todo aquele que, qualquer coisa que» (veja acima e B-D-F §293, 1; 413, 2; Rob. 727; 957), masculino: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>; 10:32; 19:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:8</a>, 10 (RHolst, ZNW 63, ’72, 122–24), 48; 14:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:21</a> (<span class=\"greek\">πᾶς</span> <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἐάν</span>, veja Jo 2:32); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:13</a> (<span class=\"greek\">πᾶς</span> <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἄν</span>, veja Jo 3:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:10</a>. Neutro (Jdth 12:14.—Jos., Ant. 5, 211 <span class=\"greek\">πᾶν</span> <span class=\"greek\">ὅ</span> = <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:37</a>, 39; 17:2b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a> (<span class=\"greek\">πᾶν</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐάν</span>).<br><br><span class=\"greek\">β</span>. Com substantivo no plural, com artigo, «todos».<br><br><span class=\"hebrew\" dir=\"rtl\">א</span> . Com substantivos: <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">γενεαί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:21</a>; GJs 6:2 e outros. <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀρχιερεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:4</a>. Cf. v. 16; 4:8; 11:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:13</a>, 31f; 6:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a>; 2:51; 6:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:18</a>; 3:18; 10:12, 43a; 14:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>; 15:11 (Ps 116:1); 16:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:26ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:18</a>; 11:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:10</a>; 6:16b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:4</a> (Gen 2:2 e 3); 9:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:7b</a>; 7:11; 15:4 e outros.—Empregado com pronome demonstrativo: <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">παρθένοι</span> <span class=\"greek\">ἐκεῖναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:7</a>. <span class=\"greek\">πάντας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τούτους</span> 26:1. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.65\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:65</a>; 2:19.—Às vezes segue o substantivo: <span class=\"greek\">τὰς</span> <span class=\"greek\">πόλεις</span> <span class=\"greek\">πάσας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:40</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">μαθηταὶ</span> <span class=\"greek\">πάντες</span> «os discípulos, todos sem exceção» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:56</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">θύραι</span> <span class=\"greek\">πᾶσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:26a</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:17</a>; 13:2a; 15:7; 16:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:3</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἱεροσολυμῖται</span> <span class=\"greek\">πάντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:5</a>.—Sobre a posição de <span class=\"greek\">ἐκεῖνος</span>, <span class=\"greek\">ἕνεκα</span>, <span class=\"greek\">πᾶς</span>, veja NTurner, VetusT 5, ’55, 208–13.<br><br><span class=\"hebrew\" dir=\"rtl\">ב</span> . Com particípios <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span>: <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κακῶς</span> <span class=\"greek\">ἔχοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:24</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">κοπιῶντες</span> 11:28; cf. 21:12; 26:52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:66</a>; 2:47; 13:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:19</a>; 2:44; 4:16; 5:5, 11; 6:15; 9:14; 28:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:7</a>; 4:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:12</a>; 4:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:9</a>; 13:24; 2J 1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:8</a>; 18:24. Após o particípio: <span class=\"greek\">οἱ</span> <span class=\"greek\">κατοικοῦντες</span> <span class=\"greek\">πάντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:14</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἡγιασμένοις</span> <span class=\"greek\">πᾶσιν</span> 20:32.—<span class=\"greek\">πάντα</span> <span class=\"greek\">τά</span>: <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γενόμενα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:31</a>. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπάρχοντα</span> 24:47; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:3</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:10</a>; 18:31; 21:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:33b</a>. Empregado com pronome demonstrativo: <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">συμβεβηκότων</span> <span class=\"greek\">τούτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:14</a>. Após o particípio: <span class=\"greek\">τὰ</span> <span class=\"greek\">γινόμενα</span> <span class=\"greek\">πάντα</span> 9:7.<br><br><span class=\"hebrew\" dir=\"rtl\">ג</span> . Com expressões preposicionais, nas quais se deve subentender <span class=\"greek\">ὄντες</span> (<span class=\"greek\">ὄντα</span>) (TestAbr A 4 p. 81, 24 [Stone p. 10] <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τραπέζης</span>; 4 [6] Esdr [POxy 1010] <span class=\"greek\">πάντες</span> <span class=\"greek\">σου</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πεδίοις</span>): <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:32</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:9</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μνημείοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:28</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μακράν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:39</a>. Cf. 5:17. <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:6</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:14</a>. <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:24</a>; 14:15 (Ex 20:11); cf. 17:24. Em posição posterior, <span class=\"greek\">οἱ</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">πάντες</span> Tit 3:15a (<span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span> JosAs 27:7).<br><br>ⓒ <span class=\"greek\">π</span>. empregado com pronomes.<br><br><span class=\"greek\">α</span>. Com pronomes pessoais: <span class=\"greek\">πάντες</span> <span class=\"greek\">ἡμεῖς</span> «todos nós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:32</a>; 10:33a; 26:14; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:16b</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">ὑμεῖς</span> «todos vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:8</a>; 26:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:10a</a>; 22:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a>; 15:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.28\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:4</a>, 7ab, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:16c</a>, 18; Tit 3:15b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:25</a>. <span class=\"greek\">πάντες</span> <span class=\"greek\">αὐτοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:33</a>; 19:17b; 20:36. Depois do pronome: <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">πάντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:3</a>. <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">πάντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:25</a>. <span class=\"greek\">αὐτοὶ</span> <span class=\"greek\">πάντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:10</a>. Com artigo: <span class=\"greek\">οἱ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἡμεῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:10</a>.<br><br><span class=\"greek\">β</span>. Com pronome demonstrativo: <span class=\"greek\">πάντες</span> <span class=\"greek\">οὗτοι</span> «todos estes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:7</a>, variante textual. Principalmente após o pronome: <span class=\"greek\">οὗτοι</span> <span class=\"greek\">πάντες</span> 1:14; 17:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:13</a>, 39. <span class=\"greek\">πάντα</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:32</a>; 24:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a>; Hm 5, 2, 5, conjectura de Joly. <span class=\"greek\">ταῦτα</span> <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:9</a>; 6:33; 13:34, 51; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.50\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:11</a>.<br><br><span class=\"greek\">γ</span>. <span class=\"greek\">πάντες</span> <span class=\"greek\">ὅσοι</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> «todos aqueles que, tudo aquilo que», masculino: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:40</a>, variante textual (em vez de <span class=\"greek\">ἅπαντες</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:8</a>. Neutro (TestAbr A 9 p. 86, 17 [Stone p. 20]; TestJob 4:2; GrBar 7:2; Philo, Aet. M. 15; 28; Jos., Ant. 8, 242; Just., A I, 44, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:12</a>; 13:46; 18:25; 21:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:24</a>; 12:44b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:41</a>. <span class=\"greek\">πάντες</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἄν</span> Hs 7:7.<br><br>ⓓ Substantivado.<br><br><span class=\"greek\">α</span>. <span class=\"greek\">πάντες</span>, <span class=\"greek\">πᾶσαι</span> «todos, todas as pessoas» (mesmo quando se trata de somente duas pessoas = «ambos»: Appian, Bell. Civ. 2, 27 §105 [César e Pompeu]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>; 14:20; 15:37; 21:26; 26:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:37</a>; 5:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:63</a> e frequentemente. <span class=\"greek\">πάντες</span> <span class=\"greek\">ἥμαρτον</span> «todos pecaram» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a> (sobre a pecaminosidade de <span class=\"greek\">πάντες</span>, cf. dito de Bias em <span class=\"greek\">πολύς</span> 1a<span class=\"greek\">β</span><span class=\"hebrew\" dir=\"rtl\">א</span>; FDanker, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:12</a>, Sin under Law, NTS 14, ’68, 430, n. 1).—<span class=\"greek\">οὐ</span> <span class=\"greek\">πάντες</span> «nem todos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:16</a>.—<span class=\"greek\">πάντων</span> como genitivo partitivo e comparativo, <span class=\"greek\">ὕστερον</span> <span class=\"greek\">πάντων</span> «por último de todos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:27</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:22</a>, 43. Até em referência a um feminino (Thu. 4, 52, 3; Aristoph., Av. 472), <span class=\"greek\">ἐντολὴ</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">πάντων</span> «o primeiro mandamento de todos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:28</a> (mas veja B-D-F §164, 1).<br><br><span class=\"greek\">β</span>. <span class=\"greek\">πάντα</span> «todas as coisas, tudo». Absolutamente (Chrysippus em Stob., Ecl. 1, 1, 26 p. 31 W.; Ps.-Aristot., De Mundo 6; M. Ant. 4, 23; Ael. Aristid. 43, 9 K.=1 p. 3 D.: <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">Ζεύς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">πάντα</span>; Herm. Wr. 5, 10; Hino a Selene em PGM 4, 2838f <span class=\"greek\">ἐκ</span> <span class=\"greek\">σέο</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">πάντ</span>’ <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σ</span>’, <span class=\"greek\">αἰώνιε</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">τελευτᾷ</span> [veja 4d<span class=\"greek\">β</span>]; PGM 5, 139; PKöln VI, 245, 16, sobre Atena [veja os comentários do editor]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27</a> = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:22</a> (veja a bibliografia relativa a esta passagem em <span class=\"greek\">υἱός</span> 2d<span class=\"greek\">β</span>. A palavra <span class=\"greek\">πάντα</span> é entendida de diversas maneiras: acerca de autoridade e poder [assim ASchlatter (Mt), FBüchsel (TW II 173) e outros] ou acerca de conhecimento e ensino: ENorden [Agn. Th. 288], TZahn [Mt], Grundmann [Lk] e outros; também JFitzmyer: «o conhecimento da relação recíproca entre ele próprio e Deus» [AB Comm. Luke II 874]. IMarshall [Lk] segue BReicke [TW V 993 n. 289] e adota ambos, poder e conhecimento); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:3</a>; 3:35; 21:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:10</a>; 15:27a (Ps 8:7), b, 28cd (<span class=\"greek\">πάντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span>, com matiz algo diferente: Dio Chrys. 54 [71], 1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:22a</a> (Ps 8:7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:5</a>. Aqui pode-se classificar <span class=\"greek\">ὁ</span> <span class=\"greek\">ὢν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">θεός</span> (cf. Aristobulus em Eus., PE 8, 10, 10; 13, 12, 4 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>; Porphyr., Vi. Plot. 23 <span class=\"greek\">τῷ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">θεῷ</span>), «Deus, que governa sobre todos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:5</a> (<span class=\"greek\">θεός</span> 2). <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">δεσπότης</span> GJs 20:3 (códices); cf. 11:2.—Acerca de uma totalidade subentendida pelo contexto: <span class=\"greek\">πάντα</span> <span class=\"greek\">ἀποδώσω</span> <span class=\"greek\">σοι</span> «tudo te pagarei» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:26</a>. Cf. 22:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:28</a> (veja Black em <span class=\"greek\">συνεργέω</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:10</a>; Tit 1:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:27</a>; GJs 18:3, códices. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐστιν</span> «tudo é vosso, pertence a vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:21</a>, cf. 22 (Plut., Cic. 873 [25, 4] <span class=\"greek\">πάντα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σοφοῦ</span> <span class=\"greek\">εἶναι</span>; Diog. L. 6, 72). <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑμῶν</span> «tudo o que fazeis» 16:14. <span class=\"greek\">πρῶτον</span> <span class=\"greek\">πάντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1</a>. <span class=\"greek\">πάντα</span> quatro vezes como anáfora (repetição retórica) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:7</a> (cf. Libanius, Or. 3 p. 275, 4 <span class=\"greek\">πάντα</span> <span class=\"greek\">φθεγγόμενοι</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐργαζόμενοι</span>, <span class=\"greek\">πάντα</span> <span class=\"greek\">χαριζόμενοι</span>).—O acusativo de especificação tem quase o valor de um advérbio (B-D-F §154; Rob. 487), <span class=\"greek\">πάντα</span> «em todos os aspectos, de todas as maneiras, inteiramente» (Hom. e outros; Aelian, VH 12, 25; Jos., Ant. 9, 166; SibOr 3, 205; Ath. 35, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:35</a> (talvez «sempre», como Ps.-Lucian, Asin. 22 p. 590); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:25b</a>. <span class=\"greek\">πάντα</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀρέσκω</span> (veja <span class=\"greek\">ἀρέσκω</span> 2a) 10:33; 11:2. Cf. KGrobel, JBL 66, ’47, 366 e veja <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> em 4d<span class=\"greek\">β</span> abaixo.—Com preposição: <span class=\"greek\">εἰς</span> <span class=\"greek\">πάντα</span> «em todos os aspectos, de todas as maneiras» (Pla., Charm. 6, 158a, Leg. 5, 738a; Appian, Iber. 17 §64, Bell. Civ. 4, 92 §385; BGU 798, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:9</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> «em todos os aspectos, de todas as maneiras» (PGiss 69, 8; Appian, Bell. Civ. 2, 112 §467 [aqui <span class=\"greek\">ἐν</span> <span class=\"greek\">ἅπασιν</span> = «em todos os aspectos»]; Just., D. 80, 1 <span class=\"greek\">ἀσφαλὴς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:7</a>; 4:5; Tit 2:9, 10b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:4</a>, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:11</a>. Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:23b</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τούτοις</span> «em tudo isso (ou além de tudo isso)» (Sir 48:15; Job 2:10; 12:9; cf. Plut., Mor. 98f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:26</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span>, veja <span class=\"greek\">κατά</span> B 6. <span class=\"greek\">περὶ</span> <span class=\"greek\">πάντων</span> «de todas as maneiras» (Mitt-Wilck I/2, 6, 9; SibOr 1, 198) 3J 2. <span class=\"greek\">πρὸ</span> <span class=\"greek\">πάντων</span> «acima de tudo, especialmente» (PRein 18, 27 [II a.C.]; BGU 811, 3; PAmh 135, 2; Just., D. 7, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:8</a>.<br><br>② Qualquer entidade de uma totalidade, qualquer e cada um, qualquer.<br><br>ⓐ Como adjetivo com substantivo no singular sem artigo, «cada, qualquer um, um qualquer, absolutamente qualquer»: <span class=\"greek\">μὴ</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">πιστεύετε</span> «não creiais em qualquer espírito» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:1</a>. <span class=\"greek\">περιφερόμενοι</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">ἀνέμῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διδασκαλίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:14</a>. <span class=\"greek\">περὶ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">πράγματος</span> «sobre qualquer assunto» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:19</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">αἰτίαν</span> «por qualquer motivo» 19:3. Cf. 4:4 = <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:4</a>, variante textual (Dt 8:3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4b</a> (sobre <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θλίψει</span> <span class=\"greek\">ἡμῶν</span> v. 4a, veja 3b abaixo).<br><br>ⓑ Substantivado, sem artigo.<br><br><span class=\"greek\">α</span>. <span class=\"greek\">πᾶς</span> «todos sem exceção» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a>.<br><br><span class=\"greek\">β</span>. <span class=\"greek\">πᾶν</span>, com preposição: <span class=\"greek\">διὰ</span> <span class=\"greek\">παντός</span>, veja <span class=\"greek\">διά</span> A 2a. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντί</span> «em todos os aspectos ou modos, em tudo» (Pla., Symp. 194a; X., Hell. 5, 4, 29; SIG 1169, 27; Sir 18:27; 4 Macc 8:3; GrBar 9:8) <span class=\"greek\">πλουτίζεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:8</a>; 7:5, 11, 16; 8:7; 9:8b; 11:6a, 9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:18</a>.<br><br>③ Marcador do grau mais elevado de alguma coisa, todo.<br><br>ⓐ Como adjetivo com substantivo no singular sem artigo: «pleno, máximo, todo» (Pla., Rep. 9, 575a; Demosth. 18, 279 e outros; inscrições, frequente em elogios; papiros: New Docs 8 p. 62, 10 <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιμελείας</span> «com toda fidelidade e solicitude»; LXX; Tat. 39, 1 <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀκριβείας</span>) <span class=\"greek\">μετὰ</span> <span class=\"greek\">παρρησίας</span> <span class=\"greek\">πάσης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:29</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">ἀσφαλείᾳ</span> 5:23. <span class=\"greek\">πάσῃ</span> <span class=\"greek\">συνειδήσει</span> <span class=\"greek\">ἀγαθῇ</span> «com toda a boa consciência» 23:1. Cf. 17:11; 24:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:8b</a>; 12:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:2</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">προσκαρτερήσει</span> «com a máxima perseverança» 6:18c. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:20</a>; 2:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:11ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:2b</a>, 11; 3:4; 4:9; 5:2; Tit 2:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a>; Jd 3 e outros. <span class=\"greek\">ὑπομένειν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ὑπομονήν</span> «exercitar a perseverança paciente até o limite» Pol 9:1.<br><br>ⓑ Em sentido afim, como adjetivo com substantivo no singular acompanhado do artigo: «todo», <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θλίψει</span> <span class=\"greek\">ἡμῶν</span> «em toda a nossa aflição» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:4a</a> (sobre <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">θλίψει</span> v. 4b, veja 2a acima); 7:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:7</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μνείᾳ</span> <span class=\"greek\">ὑμῶν</span> «em toda lembrança de vós» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:3</a>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μέριμναν</span> <span class=\"greek\">ὑμῶν</span> «toda a vossa preocupação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:7</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">χρόνον</span> AcPlCor 2:4; <span class=\"greek\">τὴν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σάρκα</span> 2:11 (cf. 1a<span class=\"greek\">α</span>).<br><br>④ Relativo a um alto grau de integridade ou totalidade, inteiro, todo.<br><br>ⓐ Como adjetivo com substantivo no singular sem artigo, «todo, inteiro», antes de nomes próprios, geralmente geográficos (X., Hell. 4, 8, 28 <span class=\"greek\">προστάται</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">Λέσβου</span> <span class=\"greek\">ἔσονται</span> e outros; LXX): <span class=\"greek\">πᾶσα</span> <span class=\"greek\">Ἱεροσόλυμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:3</a> (veja <span class=\"greek\">Ἱερ</span>.). <span class=\"greek\">πᾶς</span> <span class=\"greek\">Ἰσραήλ</span> (3 Km 8:65; 11:16; 1 Esdr 1:19; 5:45, 58; Jdth 15:14) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:26</a> (veja W-S. §20, 11a e b; Rob. 772). O AT também é a origem de <span class=\"greek\">πᾶς</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">Ἰσραήλ</span> (1 Km 7:2, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a> e, quanto ao assunto, <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> 17:26b (mas Gen 2:6 tem <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, e 7:23; 11:4, 8, 9 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">προσώπου</span> [ou <span class=\"greek\">πρόσωπον</span>] <span class=\"greek\">πάσης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>).—Talvez <span class=\"greek\">πᾶσα</span> <span class=\"greek\">οἰκοδομή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:21</a> (veja W-S. §20:11 b; Rob. 772; Mlt-Turner 199f; MDibelius, Hdb. ad loc.; M. Ant. 6, 36, 1; OGI 383, 86ff).<br><br>ⓑ Com substantivo no singular com artigo: «inteiro, todo». Antes do substantivo com artigo: <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἰουδαία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">περίχωρος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:5</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγέλη</span> «todo o rebanho» 8:32. Cf. v. 34; 13:2; 21:10; 27:25, 45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:13</a>; 4:1. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀλήθεια</span> 5:33. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κτίσις</span> «toda a criação» (TestAbr A 13 p. 92, 7 [Stone p. 32]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:22</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:10</a>; 2:1, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:9</a>, 11; 5:21; 15:12. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:19b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:6</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σπέρμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:16</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> 9:17 (Ex 9:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:25</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γνῶσις</span>, <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:2bc</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλήρωμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:19</a>; 2:9. <span class=\"greek\">πᾶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:19</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:19bc</a>. Com pronome demonstrativo <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">οὗτος</span> «todo este povo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:13</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀφειλὴ</span> <span class=\"greek\">ἐκείνη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:32</a>.—Após o substantivo com artigo: <span class=\"greek\">τὴν</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">πᾶσαν</span> «toda a questão do julgamento» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:22</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span> <span class=\"greek\">πᾶσαν</span> «à verdade em toda sua extensão» 16:13. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐξουσίαν</span> … <span class=\"greek\">πᾶσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:12</a>.<br><br>ⓒ <span class=\"greek\">πᾶς</span> e <span class=\"greek\">πάντες</span> ocorrem atributivamente entre o artigo e o substantivo, quando o substantivo é visto como um todo, por oposição a seus componentes individuais (cf. Kühner-G. I 632f).<br><br><span class=\"greek\">α</span>. Singular (Thu. 2, 7, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">πᾶς</span> <span class=\"greek\">ἀριθμόσ</span> = «o número total»; 8, 93, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">πλῆθος</span>; X., Mem. 1, 2, 8 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">βίον</span>; Pla., Gorg. 470e <span class=\"greek\">ἡ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">εὐδαιμονία</span>; 2 Macc 2:17; 3 Macc 1:29; 6:14; 4 Macc 3:8) <span class=\"greek\">ὁ</span> <span class=\"greek\">πᾶς</span> <span class=\"greek\">νόμος</span> «a lei inteira» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:14</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">χρόνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:18</a>.<br><br><span class=\"greek\">β</span>. Plural (X., An. 5, 6, 7 <span class=\"greek\">οἱ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἄνθρωποι</span>; Pla., Theaet. 204a <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">μέρη</span>): <span class=\"greek\">αἱ</span> <span class=\"greek\">πᾶσαι</span> <span class=\"greek\">ψυχαί</span> «todas as almas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:37</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">Ἰουδαῖοι</span> 21:21. <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἅγιοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:15</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἀδελφοί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:2</a>.—Com numerais (Hdt. 7, 4; Thu. 1, 60, l), <span class=\"greek\">οἱ</span> <span class=\"greek\">πάντες</span> <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">δώδεκα</span> «o número total dos homens era aproximadamente doze» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:7</a>.—JBover, Uso del adjetivo singular <span class=\"greek\">πᾶς</span> en San Pablo: Biblica 19, ’38, 411–34.<br><br>ⓓ Substantivado.<br><br><span class=\"greek\">α</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">πάντες</span> «todos (eles)» (em oposição a uma parte) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:32ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:22</a> (veja HChadwick, NTS 1, ’55, 261–75); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:21</a>. «(Nós, eles) todos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:64</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:14b</a>. <span class=\"greek\">μέχρι</span> <span class=\"greek\">καταντήσωμεν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πάντες</span> «até que todos nós cheguemos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:13</a>.<br><br><span class=\"greek\">β</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>. Em sentido absoluto, referente à totalidade da criação, «todas as coisas, o universo» (Pla., Ep. 6, 323d <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">θεός</span>; hino a Selene em EAbel, Orphica [1885] 294, 36 <span class=\"greek\">εἰς</span> <span class=\"greek\">σὲ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τελευτᾶ</span> [veja 1d<span class=\"greek\">β</span>, início]; Herm. Wr. 13, 17 <span class=\"greek\">τ</span>. <span class=\"greek\">κτίσαντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>; JosAs 8:2 <span class=\"greek\">ζωοποιήσας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>; Philo, Spec. Leg. 1, 208, Rer. Div. Her. 36, Somn. 1, 241; Just., A I, 67, 2 <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιητὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span>; PGM 1, 212 <span class=\"greek\">κύριε</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span>; 4, 3077) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:36</a> (Musaeus: Vorsokr. 2 A 4 [em Diog. L. 1, 3] <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ταὐτὸν</span> <span class=\"greek\">ἀναλύεσθαι</span>. Cf. Norden, Agn. Th. 240–50); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:6ab</a>; 15:28ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:9</a>; 4:10b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:16ab</a>, 17b (HHegermann, D. Vorstellung vom Schöpfungsmittler etc., TU 82, ’61, 88ff); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a>; 2:10ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:11</a>; 1 Cl 34:2; PtK 2 (quatro vezes).—Em sentido relativo, indicado pelo contexto, «tudo» (<span class=\"greek\">Κυπρ</span>. I p. 42 no. 29 <span class=\"greek\">τὰς</span> <span class=\"greek\">στοὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐταῖς</span> <span class=\"greek\">πάντα</span>; PGiss 2, 14 [II a.C.] em uma conta: <span class=\"greek\">τὰ</span> <span class=\"greek\">π</span>. = «tudo em conjunto») <span class=\"greek\">ἐν</span> <span class=\"greek\">παραβολαῖς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">γίνεται</span> «tudo (= todo o ensino) é exposto em parábolas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:11</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:25b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:32b</a>. Acerca de tudo no céu e na terra que precisa ser unido e redimido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a> (EWalter, Christus u. d. Kosmos [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a>] ’48); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:20</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> «todos eles» (os membros do corpo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:19</a>. O neutro também se emprega para pessoas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a> (aqui incluindo a humanidade e tudo o mais que possui vida).—Como acusativo de especificação, quase como advérbio, <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> «em todos os aspectos» (Appian, Prooem. 6 §23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:15</a> (veja 1d<span class=\"greek\">β</span>).—Como resumo do que precede, «tudo isso» (PCairZen 741, 16; 742, 22; BGU 1509 [todos III a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:8</a>.—Além disso, <span class=\"greek\">πάντες</span> pode assumir o sentido limitado de «quase todos» (Xenophon Eph. 2, 13, 4 <span class=\"greek\">πάντας</span> <span class=\"greek\">ἀπέκτεινεν</span>, <span class=\"greek\">ὀλίγους</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζῶντας</span> <span class=\"greek\">ἔλαβε</span>. <span class=\"greek\">μόνος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἱππόθοος</span> <span class=\"greek\">ἠδυνήθη</span> <span class=\"greek\">διαφυγεῖν</span>).—Mlt-Turner 199–201.<br><br>⑤ Tudo o que, por sua espécie, pertence à classe designada pelo substantivo, «toda espécie de, toda sorte de», adjetivo usado em lugar de <span class=\"greek\">παντοδαπός</span> e <span class=\"greek\">παντοῖος</span>, ausentes de nossa literatura: <span class=\"greek\">πᾶσα</span> <span class=\"greek\">νόσος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">μαλακία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:23</a>. <span class=\"greek\">γέμουσιν</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀκαθαρσίας</span> «estão cheios de toda espécie de impureza» 23:27 (Ar. 15, 6). <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἐξουσία</span> 28:18. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἔθνους</span> «de toda espécie de nação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:5</a>. Cf. 7:22; 13:10ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:18</a>, 29. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἐπιθυμία</span> «desejo (maligno) de toda espécie» 7:8. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">γνώσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:5b</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἁμάρτημα</span> «toda espécie de pecado» 6:18. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:1</a>; 9:8bc; 10:5ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a>, 8, 21a; 4:19; 5:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:17</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">ἀγαθόν</span> Tit 1:16; 3:1. Cf. 2:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:21</a>. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">δόσις</span>, <span class=\"greek\">πᾶν</span> <span class=\"greek\">δώρημα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a> (W-S. §20, 11b). Cf. v. 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:1ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:7</a> e outros.—B. 919. Schmidt, Syn. IV, 540–54, veja <span class=\"greek\">ἕκαστος</span> e <span class=\"greek\">ὅλος</span>. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσχα, τό</h1><div class=\"entry-meta\"><span>substantivo neutro indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάσχα</span>, <span class=\"greek\">τό</span>, indeclinável (aramaico <span class=\"hebrew\" dir=\"rtl\">פַּסְחָא</span> ou <span class=\"hebrew\" dir=\"rtl\">פִּסְחָא</span>, equivalente ao hebraico <span class=\"hebrew\" dir=\"rtl\">פֶּסַח</span>.—LXX, Philo, Joseph., Just., Mel., Did.).<br><br>① Festa anual israelita que comemora o êxodo de Israel do Egito, Páscoa, celebrada no dia 14 do mês de nisã e prolongada até as primeiras horas do dia 15 (Jos., Ant. 3, 284f; veja também Ex 12–13; cf. Mishná, Pesahim). A ela seguia-se imediatamente a Festa dos Pães Asmos (Mazzoth; <span class=\"greek\">ἄζυμος</span> 2), do dia 15 ao 21. O uso popular fundiu as duas festas e as tratou como uma unidade, como efetivamente eram na prática (veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:1</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:12</a> abaixo.—Assim também Philo e Joseph.: GAmadon, ATR 27, ’45, 109–115; cf. BWambacq, Biblica 62, ’81, 499–518). <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. «a Páscoa (festa)» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:23</a>; 11:55b; 12:1; 18:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:4</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. «nesta Páscoa» GEb 311, 48; 50f (reformulação de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:15</a> segundo uma perspectiva encratita). <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> «a Páscoa dos judeus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:13</a>; 11:55a. <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>., <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑορτὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἰουδαίων</span> 6:4; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑορτὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:1</a>. <span class=\"greek\">παρασκευὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">π</span>. (veja <span class=\"greek\">παρασκευή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:14</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἑορτὴ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">λεγομένη</span> <span class=\"greek\">πάσχα</span> «a Festa dos Pães Asmos, chamada Páscoa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:1</a> (Jos., Ant. 14, 21 <span class=\"greek\">τῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀζύμων</span> <span class=\"greek\">ἑορτῆς</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">λέγομεν</span>; 17, 213; 18, 29, Bell. 2, 10. HSchürmann, Der Paschamahlbericht, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:7</a>–14, 15–18, ’53). <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">γίνεται</span> «a Páscoa é celebrada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:2</a>.<br><br>② Cordeiro sacrificado para a celebração da Páscoa, cordeiro pascal. <span class=\"greek\">θύειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. (<span class=\"hebrew\" dir=\"rtl\">שָּׁחַט</span> <span class=\"hebrew\" dir=\"rtl\">הַפֶּסַח</span>.—Ex 12:21; Dt 16:2, 6; 1 Esdr 7:12; Just., D. 40, 1) «imolar o cordeiro pascal» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:12a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:7</a>; figuradamente acerca de Cristo e sua morte sangrenta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:7</a> (ELohse, Märtyrer u. Gottesknecht, ’55, 141–46). <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. (<span class=\"hebrew\" dir=\"rtl\">אָכַל</span> <span class=\"hebrew\" dir=\"rtl\">הַפֶּסַח</span>.—2 Ch 30:18 [<span class=\"greek\">φασεκ</span>]; 2 Esdr 6:21) «comer o cordeiro pascal» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:12b</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:11</a>, 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:28</a>; GEb 311, 47 (aqui ocorre o verbo <span class=\"greek\">ἑτοιμάζειν</span>, tomado da terminologia pascal [veja 3], mas <span class=\"greek\">π</span>. conserva seu sentido específico de «cordeiro pascal».—Mel., P. 16, 101 <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. <span class=\"greek\">βιβρώσκεται</span>; Orig., C. Cels. 1, 70, 4).—Para bibliografia, veja <span class=\"greek\">ἐσθίω</span> 1a.<br><br>③ Refeição da Páscoa. <span class=\"greek\">ἑτοιμάζειν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. «preparar a refeição pascal» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:8</a>, 13. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. (frequente na LXX) «realizar ou celebrar a Páscoa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a>.<br><br>④ No uso cristão posterior, a festa da Páscoa cristã (<span class=\"greek\">τὸ</span> <span class=\"greek\">π</span>. Hippol., Ref. 8, 5) <span class=\"greek\">τὸ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">π</span>. Dg 12:9.—GBeer, Pesachim 1912 (p. 1, 1 bibliografia); Elbogen3 ’31; HGuthe, Z. Passah der jüd. Religionsgem.: StKr 96/97, 1925, 144–71; Billerb. IV 1928, 41–76: D. Passamahl; JJeremias, D. Passahfeier der Samaritaner ’32, D. Abendmahlsworte Jesu2 ’49, 3’60, tradução inglesa The Eucharistic Words of Jesus, OEhrhardt ’55, 86–184, também 3.ª tradução NPerrin ’64; Dalman, Jesus 80–160; JPedersen, Passahfest u. Passahlegende: ZAW 52, ’34, 161–75; PHeawood, ET 53, ’41/42, 295–97; FBussby, ibid. 59, ’47/48, 194f; GWalther, Jesus, d. Passalamm ’50; ESchweizer, TLZ 79, ’54, 577–91; AJaubert, La date de la Cène ’57; JSegal, The Hebrew Passover to a.d. 70 ’63; HGrass Ostergeschehen u. Osterberichte2 ’62; NFüglister, Die Heilsbedeutung des Pascha ’63; ERuckstuhl, Die Chronologie des letzten Mahles, etc. ’63 (tradução inglesa VDrapela ’65); RLeDéaut, La nuit pascale ’63; JvGoudoever, Studia Evangelica III, ’64, 254–59. A obra de AJaubert acima foi traduzida como The Date of the Last Supper por IRafferty ’65; tese de Jaubert rejeitada por EKutsch, VetusT 11, ’61, 39–47; NTheiss, Int 48, ’94, 17–35, em relação ao Sêder.—EDNT. ABD VI 764f (bibliografia). TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πάσχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πάσχω</span>, futuro da 3.ª pessoa singular <span class=\"greek\">παθεῖται</span> (2 Cl 7:5; variante textual <span class=\"greek\">πείσεται</span>; cf. Reinhold p. 74; B-D-F §74, 3), da 3.ª plural <span class=\"greek\">παθοῦνται</span> Hs 8, 10, 4; 2.º aoristo <span class=\"greek\">ἔπαθον</span>; perfeito <span class=\"greek\">πέπονθα</span>, particípio <span class=\"greek\">πεπονθώς</span>; mais-que-perfeito da 3.ª pessoa plural <span class=\"greek\">ἐπεπόνθεισαν</span> Wsd 18:1 (Hom.+), «experimentar alguma coisa, receber determinado tratamento» (<span class=\"greek\">π</span>. exprime a ideia passiva correspondente à ideia ativa expressa por <span class=\"greek\">ποιέω</span>), acerca de tudo o que sucede a alguém, seja bom ou mau. O uso, porém, desenvolveu-se de tal maneira que <span class=\"greek\">π</span>. passou a ser empregado cada vez menos frequentemente em sentido favorável, e nunca nesse sentido sem alguma indicação clara, ao menos do contexto, de que se trata de algo bom. Em nossa literatura ocorre:<br><br>① Uma única vez no sentido de experimentar algo (agradável) (acerca de alguém que recebe bênção especial: Pind., P. 3, 104 <span class=\"greek\">εὖ</span> <span class=\"greek\">πασχέμεν</span>, N. 1, 32 <span class=\"greek\">εὖ</span> <span class=\"greek\">παθεῖν</span>; Antiphanes 252, 2b <span class=\"greek\">ἀγαθὸν</span> <span class=\"greek\">πάσχει</span>; Diod S 20, 102, 2 <span class=\"greek\">εὖ</span> <span class=\"greek\">πάσχειν</span>; Dionys. Hal. 7, 51; Plut., Mor. 1110d; Arrian, Ind. 34, 1, Peripl. 2, 4; Jos., Ant. 3, 312; POxy 1855, 8; 10; 14 <span class=\"greek\">πάσχω</span> <span class=\"greek\">ἀπόκρισιν</span>, de informação favorável) <span class=\"greek\">τοσαῦτα</span> <span class=\"greek\">ἐπάθετε</span> <span class=\"greek\">εἰκῆ</span>; «tivestes experiências tão extraordinárias em vão?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:4</a> (Procop. Soph., Ep. 18 <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">παθών</span>; Ps.-Aristot., Mirabilia 112 <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">πάσχει</span> = «ele experimenta a mesma coisa».—Diferentemente Zahn e outros; a seu ver, essa passagem pertence a 3b abaixo; como apoio a essa interpretação, veja <span class=\"greek\">τοσαῦτα</span> <span class=\"greek\">παθών</span> Ep. 56 de Apollonius of Tyana [Philostrat. I 359, 16], mas a associação com <span class=\"greek\">ἐπιχορηγέω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:5</a> sugere recebimento de benefício).—Sobre a possibilidade de jogo de palavras (<span class=\"greek\">παθεῖν</span> … <span class=\"greek\">μαθεῖν</span>), veja Betz, Gal. 134.<br><br>② Há igualmente uma única passagem na qual <span class=\"greek\">π</span>. tem significado neutro. Mesmo aí, o acréscimo de <span class=\"greek\">κακῶς</span> lhe confere conotação desfavorável: <span class=\"greek\">κακῶς</span> <span class=\"greek\">πάσχειν</span> «estar em situação penosa, sofrer um mal» (Hom. e outros; Hdt. 3, 146 e outros; Wsd 18:19; JosAs 7:4; 24:1; Philo, In Flacc. 124, Spec. Leg. 4, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:15</a> (variante textual <span class=\"greek\">ἔχει</span>).<br><br>③ Em todas as outras passagens, como sempre na LXX, em sentido desfavorável: sofrer, suportar.<br><br>ⓐ Sofrer.<br><br><span class=\"greek\">α</span>. Absolutamente (também no sentido de sofrer a morte, ser morto, [ter de] morrer: Appian, Bell. Civ. 1, 70 §321; 3, 87 §359; Arrian, Anab. 6, 10, 3; Paroem. Gr.: Zenob. 4, 60, o corvo <span class=\"greek\">ἔπαθε</span> por causa do veneno do escorpião; Herodian 1, 17, 7; Just., D. 52, 3; Mel., P. 8, 65; semelhantemente Callinus [VII a.C.], Fgm. 1, 17 G-B.[=D.3] <span class=\"greek\">ἤν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πάθῃ</span> = «se ele caísse»; Demosth. 4, 11f; Straton of Lamps., Fgm. 10 [em Diog. L. 5, 61] <span class=\"greek\">ἐάν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πάσχω</span> = «se algo me acontecer»; Diod S 13, 98, 2; Lucian, Dial. Meretr. 8, 3; Iambl., Vi. Pyth. 33, 238; Jos., Ant. 15, 65; 18, 352; CB I/2, 391 no. 254; Iren. 1, 3, 3 [Harv. I, 27, 1]) <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">με</span> <span class=\"greek\">παθεῖν</span> «antes de eu sofrer» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:15</a>. Cf. 24:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>; 3:18; 17:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:18</a> (sobre <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span>, veja <span class=\"greek\">ἐν</span> 7); 9:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:20</a>, 23; 3:17; B 7:2a; Hs 8, 10, 4. A expressão <span class=\"greek\">γῆ</span> <span class=\"greek\">πάσχουσα</span> B 6:9 parece transferir para a <span class=\"greek\">γῆ</span> o conceito filosófico da matéria passível de sofrimento (Hefele, Hilgenfeld, Veil): «terra capaz de sofrer» (Goodsp.), «terra capaz de ser moldada em ser humano» (Kleist, nota ad loc.).<br><br><span class=\"greek\">β</span>. Com complementos: <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> «pelas mãos de alguém» designa aquele que causou o sofrimento (Antiphon Orat., Fgm. 34; Ael. Aristid. 45 p. 134 D.; PAmh 78, 4; Jos., Bell. 5, 19, Ant. 10, 92; Mel., P. 75, 546ff; B-D-F §315) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:12</a> (veja também b abaixo). Também <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">χειρός</span> <span class=\"greek\">τινος</span> B 5:5b (cf. Mel., Fgm. 7 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">δεξιᾶ</span> <span class=\"greek\">Ἰσραηλίτιδος</span>). <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> «por alguém ou alguma coisa» (Appian, Bell. Civ. 1, 15 §63 <span class=\"greek\">π</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> = «sofrer por alguém»; Just., D. 121, 2 <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἀρνεῖσθαι</span> <span class=\"greek\">αὐτόν</span>, como metáfora militar: EKrentz, em Origins and Method, Festschrift JHurd ’93, 126) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:21</a> (<span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, variante textual), <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hs 9, 28, 2a. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> 8, 3, 6. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σωτηρίας</span>, <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἁμαρτωλῶν</span> MPol 17:2. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span> ISm 7:1. Também <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Nicol. Dam.: 90 Fgm. 130, 29 p. 415, 29 Jac. <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">διαδόχων</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἅπαν</span> … <span class=\"greek\">παθεῖν</span>), <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:18</a> (variante textual <span class=\"greek\">ἀπέθανεν</span>). <span class=\"greek\">περι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ἡμῶν</span> B 5:5a. <span class=\"greek\">διά</span> com acusativo, «por causa de»: <span class=\"greek\">διὰ</span> <span class=\"greek\">δικαιοσύνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:14</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> (<span class=\"greek\">αὐτοῦ</span>) Pol 8:2; Hv 3, 2, 1; Hs 9, 28, 3. <span class=\"greek\">δι</span>’ <span class=\"greek\">ἡμᾶς</span> B 7:2b. <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> Hs 9, 28, 6a. <span class=\"greek\">εἵνεκα</span> ou <span class=\"greek\">ἕνεκεν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> v 3, 1, 9; 3, 5, 2; Hs 9, 28, 5; 6b. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θέλημα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:19</a>. <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πύλης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:12</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ξύλου</span> «sobre o madeiro» B 5:13b.—Com dativo instrumental (?) <span class=\"greek\">αἰκίαις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βασάνοις</span> <span class=\"greek\">π</span>. 1 Cl 6:1, variante textual. <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">πράξεσι</span> Hs 6, 3, 4. Com dativo de modo (B-D-F §198), <span class=\"greek\">π</span>. <span class=\"greek\">σαρκί</span> «sofrer corporalmente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:1ab</a> (em b, variante textual <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκί</span>).—Com advérbio: <span class=\"greek\">ἀδίκως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:19</a>. <span class=\"greek\">ἀληθῶς</span> ISm 2b. <span class=\"greek\">δικαίως</span> (TestSim 4:3; Just., D. 110, 6) Hs 6, 3, 6a. <span class=\"greek\">ἡδέως</span> 8, 10, 4. <span class=\"greek\">προθύμως</span> 9, 28, 2b e 4. <span class=\"greek\">οὕτω</span> GPt 4:13; B 5:13a. <span class=\"greek\">ὀλίγον</span> (veja <span class=\"greek\">ὀλίγος</span> 2b<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:10</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">δοκεῖν</span> (<span class=\"greek\">δοκέω</span> 2a<span class=\"greek\">α</span>) «em aparência, aparentemente» ITr 10; ISm 2c.—<span class=\"greek\">ὡς</span> <span class=\"greek\">φονεύς</span> «sofrer punição (cf. SIG 1016, 7 <span class=\"greek\">π</span>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἱερόσυλος</span>) como assassino» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:15</a>.<br><br>ⓑ Suportar, experimentar <span class=\"greek\">τί</span> «alguma coisa» (Orig., C. Cels. 7, 13, 7; <span class=\"greek\">π</span>. <span class=\"greek\">καταστροφήν</span>; Did., Gen. 232, 11; Theoph. Ant. 2, 23 [p. 156, 6]) <span class=\"greek\">παθήματα</span> <span class=\"greek\">π</span>. «suportar sofrimentos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6</a> (<span class=\"greek\">ὧν</span>, por atração do relativo a partir de <span class=\"greek\">ἅ</span>; semelhantemente Iren. 1, 8, 2 [Harv. I 70, 4]). <span class=\"greek\">αἰκίσματα</span> 1 Cl 6:2. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">π</span>. (Jos., Ant. 13, 268; 403) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:31</a>; 9:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:22</a> (veja também abaixo); 17:25; B 7:11; AcPl Ha 8, 19. <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅμοιά</span> <span class=\"greek\">τινι</span> «as mesmas coisas que alguém» Ox 840, 3. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">κακόν</span> «não sofrer mal algum» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:5</a>. <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πονηρῶν</span> Hs 6, 3, 6b. <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">πεπονθώς</span> «como se nada lhe houvesse acontecido» MPol 8:3 (cf. TestJob 47:7 <span class=\"greek\">ὡς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">ὅλως</span> <span class=\"greek\">πεπονθώς</span>). <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:2</a>; 24:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:12</a>; 1 Cl 45:5. <span class=\"greek\">τί</span> <span class=\"greek\">παθεῖται</span>; «que terá ele de suportar?» 2 Cl 7:5 (<span class=\"greek\">πάσχειν</span> <span class=\"greek\">τι</span> = «sofrer castigo», como Pla., Leg. 10, 1, 885ab). <span class=\"greek\">μὴ</span> <span class=\"greek\">φοβοῦ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">μελλεις</span> <span class=\"greek\">πάσχειν</span> «não temas aquilo que estás para sofrer» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:10</a>. Com atração, <span class=\"greek\">ἔμαθεν</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὧν</span> <span class=\"greek\">ἔπαθεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπακοήν</span> = <span class=\"greek\">ἔμαθεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπακοὴν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τούτων</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἔπαθεν</span> «aprendeu a obediência por meio daquilo que sofreu» (isto é, embora fosse Filho de Deus, Jesus experimentou o sofrimento como meio de manifestar a extensão suprema de sua obediência) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:8</a> (sobre a consonância ou jogo de palavras, veja as referências em <span class=\"greek\">μανθάνω</span> 3). <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">τινος</span> «sofrer alguma coisa pelas mãos de alguém» (X., Hiero 7, 8, Symp. 1, 9; Jos., Ant. 7, 209; 12, 401; veja 3a<span class=\"greek\">β</span> acima) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:14</a>; B 7:5. Também <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Dio Chrys. 67 [17], 11; Lucian, D. Deor. 6, 4; Orig., C. Cels. 8, 27, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:21</a>; talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:22</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἕνεκά</span> <span class=\"greek\">τινος</span> «sofrer alguma coisa por causa de alguém» 2 Cl 1:2. Também <span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">διά</span> <span class=\"greek\">τινα</span> ISm 2a (Just., D. 117, 3; Mel., P. 59, 435). <span class=\"greek\">ὅσα</span> <span class=\"greek\">δεῖ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματός</span> <span class=\"greek\">μου</span> <span class=\"greek\">παθεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:16</a> (<span class=\"greek\">π</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> como Jos., Ant. 13, 199).—WWichmann, D. Leidenstheologie, e. Form der Leidensdeutung im Spätjudentum 1930; HVondran, D. Leidensgedanke im Spiegel d. Selbstbewusstseins Jesu: NKZ 43, ’32, 257–75; RLiechtenhan, D. Überwindung d. Leidens b. Pls. u. in d. zeitgen. Stoa: ZTK n.s. 3, 1922, 368–99; WMichaelis, Herkunft u. Bed. des Ausdrucks ‘Leiden u. Sterben J. Chr.’ ’45; HRiesenfeld, Jésus Transfiguré, ’47, 314–17 (Le Messie Souffrant … ); ELohse, Märtyrer u. Gottesknecht (Sühntod Jesu Christi), ’55; EGüttgemanns, D. leidende Apostel, ’66.—K Schelkle, Die Passion Jesu etc., ’49; JGreen, The Death of Jesus ’88; RBrown, The Death of the Messiah, 2 vols. ’94; ACollins, From Noble Death to Crucified Messiah, NTS 40, ’94, 481–503; sobre suposto antijudaísmo na narrativa da paixão segundo Lucas, veja HMerkel, NTS 40, ’94, 394–95 (bibliografia).—Schmidt, Syn. I 424–441. DELG. M-M. EDNT. DLNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάταρα, ων, τά</h1><div class=\"entry-meta\"><span>topônimo neutro plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πάταρα</span>, <span class=\"greek\">ων</span>, <span class=\"greek\">τά</span>, neutro plural, Pátara (Hdt. 1, 182; Strabo 14, 3, 3; OGI 441, 209; SibOr 3, 441; 4, 112.—Sobre a grafia, veja B-D-F §42, 3; Rob. 183), cidade da Lícia, na costa sudoeste da Ásia Menor. Paulo fez escala ali em sua viagem de Corinto a Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:1</a>.—Pauly-W. XVIII 2555–61; Kl. Pauly IV 544f; BHHW III 1400; PECS 679f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πατάσσω</span>, futuro <span class=\"greek\">πατάξω</span>; 1.º aoristo <span class=\"greek\">ἐπάταξα</span>. Passivo: futuro da 3.ª pessoa singular <span class=\"greek\">παταχθήσεται</span> (Just., D. 53, 5); infinitivo aoristo <span class=\"greek\">παταχθῆναι</span> (Mel., P. 34, 233), particípio neutro <span class=\"greek\">παταχθέν</span> (AcPl Ha 5, 11); (cf. <span class=\"greek\">πάταγος</span> «estrondo»; Hom.+; inscrições, papiros, LXX; PsSol 17:35; TestJob 20:6; TestLevi, JosAs; GrBar 3:8; AssMos Fgm. j; Hecataeus Hist.: 264 Fgm. 21 Jac. [em Jos., C. Ap. 1, 203]; Just., Mel.).<br><br>① Desferir fisicamente um golpe, bater, golpear.<br><br>ⓐ Acerca de golpe leve ou empurrão, <span class=\"greek\">τὶ</span> «alguma coisa» (Aesop, Fab. 246 P.=108 H.; 88 Ch.; 278 H-H. <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span>) <span class=\"greek\">τὴν</span> <span class=\"greek\">πλευράν</span> <span class=\"greek\">τινος</span> «golpear o lado de alguém para acordá-lo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:7</a>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατάξαι</span> <span class=\"greek\">αὐτά</span> «para conduzir (ovelhas) para a frente» GJs 18:3, códices. Absolutamente, mas com o acusativo facilmente subentendido pelo contexto, sobre tocar com uma vara, Hs 9, 6, 4.<br><br>ⓑ Acerca de golpe forte; com acusativo de pessoa (Demosth. 21, 33 <span class=\"greek\">τὸν</span> <span class=\"greek\">ἄρχοντα</span>; Appian, Bell. Civ. 2, 17 §64 <span class=\"greek\">δᾳδοῦχον</span> <span class=\"greek\">ἐπάταξε</span> <span class=\"greek\">ξίφει</span>) <span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">δοῦλον</span> «ferir o servo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:51</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:50</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ὠτίον</span> <span class=\"greek\">παταχθέν</span> «a orelha atingida (pelo granizo)» AcPl Ha 5, 11. Absolutamente, «golpear», <span class=\"greek\">ἐν</span> <span class=\"greek\">μαχαίρῃ</span> «à espada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:49</a> (cf. TestLevi 6:5 <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">στόματι</span> <span class=\"greek\">μαχαίρας</span>).<br><br>ⓒ Acerca de golpe que mata, abater, matar <span class=\"greek\">τινά</span> «alguém» (PHal 1, 196; UPZ 19, 8 [159 a.C.]; BGU 1024 III, 17; JosAs 23:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:27</a>; B 5:12 (os três conforme Zech 13:7; acerca do assunto, veja Jos., Ant. 8, 404); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:24</a> (Ex 2:12).<br><br>② Infligir alguma calamidade, ferir, extensão figurada de 1. Quando se refere a seres transcendentes, não é possível determinar se envolve toque ou golpe efetivo nem até que ponto (cf. Gen 8:21; Ex 9:15; 12:23; Num 14:12; Dt 28:22; 4 Km 6:18; 2 Macc 9:5 e frequentemente na LXX; PsSol 17:35; TestJob 20:6 [sobre Satanás]. Veja também SIG 1240, 11; PHamb 22, 7) <span class=\"greek\">ἐπάταξεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">κυρίου</span> «um anjo do Senhor o feriu» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:23</a>. Empregado com <span class=\"greek\">ἐν</span> instrumental e dativo: acerca das duas testemunhas, <span class=\"greek\">π</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">πληγῇ</span> «ferir a terra com toda espécie de praga» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:6</a> (PGM 12, 368 <span class=\"greek\">θεόν</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">πατάξαντα</span> <span class=\"greek\">γῆν</span>; 2 Macc 9:5 <span class=\"greek\">π</span>. <span class=\"greek\">πληγῇ</span>). Acerca do Logos como juiz do mundo, <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῇ</span> (isto é, a <span class=\"greek\">ῥομφαία</span> que sai de sua boca) <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> «ferir as nações» 19:15.—DELG s.v. <span class=\"greek\">πάταγος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πατέω</span>, futuro <span class=\"greek\">πατήσω</span>; 1.º aoristo <span class=\"greek\">ἐπάτησα</span> LXX. Passivo: futuro da 3.ª pessoa singular <span class=\"greek\">πατηθήσεται</span> (TestZeb); aoristo <span class=\"greek\">ἐπατήθην</span> (Hom. e outros; papiros, LXX; En 1:4; TestLevi 18:12; TestZeb 9:8, variante textual; JosAs 23:8 [cód. A em lugar de <span class=\"greek\">ἐπάταξε</span>]; AscIs 3:3; Philo, Just.), pisar com os pés (sobre algo).<br><br>① Pôr o pé em, pisar, andar sobre, transitivo.<br><br>ⓐ Pisar <span class=\"greek\">τὶ</span> «alguma coisa» (Herodas 8, 74), <span class=\"greek\">τὴν</span> <span class=\"greek\">ληνόν</span> (veja <span class=\"greek\">ληνός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:15</a>; passivo 14:20. Acerca de uma pedra, <span class=\"greek\">ὁ</span> <span class=\"greek\">πατούμενος</span> «aquilo que é pisado» Dg 2:2.<br><br>ⓑ Pôr o pé em, pisar, acerca de lugar (Aeschyl. e outros; LXX), <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐλήν</span> «o pátio» B 2:5 (Is 1:12). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἁγνευτήριον</span> Ox 840 12; <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερόν</span> ibid. 17; 20.<br><br>② Pisar pesadamente, com implicação de intenção destrutiva, pisotear, transitivo.<br><br>ⓐ Pisar, pisotear (Iambl., Vi. Pyth. 31, 193), acerca da passagem indisciplinada e tumultuosa de um exército vitorioso por cidade conquistada. Sua negligência, que não reconhece limites, faz <span class=\"greek\">π</span>. assumir o sentido de «maltratar, abusar» (assim <span class=\"greek\">πατέω</span> em Plut., Tim. 14, 2; Lucian, Lexiph. 10 e outros; Philo, In Flacc. 65) e «pisar com desprezo» (veja 2b; em Heliod. 4, 19, 8 <span class=\"greek\">π</span>. <span class=\"greek\">πόλιν</span> significa propriamente «saquear uma cidade»). <span class=\"greek\">τὴν</span> <span class=\"greek\">πόλιν</span> <span class=\"greek\">πατήσουσιν</span> «pisotearão a cidade» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:2</a>; passivo (Jos., Bell. 4, 171 <span class=\"greek\">πατούμενα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἅγια</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:24</a> (<span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἐθνῶν</span>).<br><br>ⓑ Extensão figurada de a: pisotear por desprezo ou desdém (Il. 4, 157 <span class=\"greek\">ὅρκια</span>; Soph., Aj. 1335, Antig. 745 e outros; Herodian 8, 5, 9; Jos., Bell. 4, 258 <span class=\"greek\">τ</span>. <span class=\"greek\">νόμους</span>), <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰσχύνης</span> <span class=\"greek\">ἔνδυμα</span> <span class=\"greek\">πατεῖν</span> «desprezar (= lançar fora com desdém) a veste da vergonha» (veja <span class=\"greek\">αἰσχύνη</span> 1) GEg 252, 57.<br><br>③ Deslocar-se a pé, andar, caminhar (não no sentido de «passear») (desde Pind., P. 2, 85 <span class=\"greek\">ἄλλ</span>’ <span class=\"greek\">ἄλλοτε</span> <span class=\"greek\">πατέων</span> <span class=\"greek\">ὁδοῖς</span> <span class=\"greek\">σκολιαῖς</span>, sobre alguém que se move contra adversário como uma raposa, pisando ora aqui, ora ali, sem seguir linha reta), com implicação de que a experiência não é planejada, intransitivo; <span class=\"greek\">πατεῖν</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">ὄφεων</span> «pisar sobre serpentes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a> (<span class=\"greek\">ἐπάνω</span> 1b e cf. TestLevi 18:12.—Diod S 3, 50, 2f trata do perigo de morte ao <span class=\"greek\">πατεῖν</span> sobre <span class=\"greek\">ὄφεις</span>).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατήρ, πατρός, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πατήρ</span>, <span class=\"greek\">πατρός</span>, <span class=\"greek\">ὁ</span> (Hom.+), acusativo por vezes <span class=\"greek\">πατέραν</span> (ApcEsdr 2:6 p. 25, 26 Tdf.); vocativo <span class=\"greek\">πάτερ</span>; em lugar deste, o nominativo com artigo <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:6</a>.—As variantes textuais <span class=\"greek\">πατήρ</span> sem artigo, em função de vocativo, em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:11</a>, 21, 24 e 25 são consideradas por B-D-F §147, 3 erros de copista (mas já no século II d.C. BGU 423, 11 apresenta <span class=\"greek\">κύριέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">πατήρ</span>. Talvez mesmo PPar 51, 36 [159 a.C.]). Veja também W-S. §29, 4b e Mlt-H. 136; «pai».<br><br>① Ascendente biológico imediato, genitor.<br><br>ⓐ Masculino, pai (de Noé, Did., Gen. 165, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:22</a>; 4:21f; 8:21; 10:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:40</a>; 15:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a> (conforme Mal 3:23); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:1</a>; B 13:5 e outros. <span class=\"greek\">οἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πατέρες</span> «nossos pais carnais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9a</a>.<br><br>ⓑ Masculino e feminino conjuntamente como pais, <span class=\"greek\">οἱ</span> <span class=\"greek\">πατέρες</span> «pais» (Pla., Leg. 6, 772b; Dionys. Hal. 2, 26; Diod S 21, 17, 2; X. Eph. 1, 11; 3, 3; Kaibel 227) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:23</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:21</a> (Apollon. Rhod. 4, 1089, a respeito de pais inclinados a tornar-se <span class=\"greek\">λίην</span> <span class=\"greek\">δύσζηλοι</span> em relação aos filhos).<br><br>② Pessoa da qual alguém descende, geralmente afastada por várias gerações, antepassado, ancestral, progenitor: acerca de Abraão (Jos., Ant. 14, 255 <span class=\"greek\">Ἀ</span>., <span class=\"greek\">πάντων</span> <span class=\"greek\">Ἑβραίων</span> <span class=\"greek\">πατήρ</span>; Just., D. 100, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.73\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:73</a>; 16:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:39</a>, 53, 56; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2b</a>. Acerca de Isaque, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:10</a>. Jacó, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:12</a> (JosAs 22:5). Davi, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a>. Plural <span class=\"greek\">οἱ</span> <span class=\"greek\">πατέρες</span> «os antepassados, ancestrais» (Hom. e outros; frequente na LXX; En 99:14; PsSol 9:10; ParJer 4:10; Jos., Ant. 13, 297; Just., D. 57, 2 e 136, 3; Mel., P. 87, 654) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:30</a>, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:55</a>; 6:23, 26; 11:47f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:20</a>; 6:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>, 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:1</a>; 8:9 (Jer 38:32); B 2:7 (Jer 7:22); 5:7; 14:1; PtK 2 p. 15, 6 (Jer 38:32).<br><br>③ Aquele que proporciona formação moral e intelectual, pai.<br><br>ⓐ Em sentido positivo (Epict. 3, 22, 81f: o cínico supervisiona a formação de todas as pessoas como seu <span class=\"greek\">πατήρ</span>; Procop. Soph., Ep. 13; Ael. Aristid. 47 p. 425 D.: Platão como <span class=\"greek\">τῶν</span> <span class=\"greek\">ῥητόρων</span> <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">διδάσκαλος</span>; Aristoxenus, Fgm. 18: Epaminondas é <span class=\"greek\">ἀκροατής</span> do pitagórico Lysis e o chama de <span class=\"greek\">πατήρ</span>; Philostrat., Vi. Soph. 1, 8 p. 10, 4: o <span class=\"greek\">διδάσκαλος</span> como <span class=\"greek\">πατήρ</span>) <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μυρίους</span> <span class=\"greek\">παιδαγωγοὺς</span> <span class=\"greek\">ἔχητε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλοὺς</span> <span class=\"greek\">πατέρας</span> «ainda que tenhais dez mil tutores em Cristo, não tendes muitos pais» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:15</a> (cf. GrBar 13:4 <span class=\"greek\">εἰς</span> <span class=\"greek\">πνευματικοὺς</span> <span class=\"greek\">πατέρας</span>; sobre o assunto, ADieterich, Mithraslit. 1903, 52; 146f; 151; Rtzst., Mysterienrel.3 40: «ele [o 'iniciado'] por meio dessas instruções torna-se o pai do noviço. Encontramos exemplos incontestáveis de <span class=\"greek\">πατήρ</span> como título no culto de Ísis em Delos, nas comunidades frígias de mistérios, no culto de Mitra, entre adoradores do <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὕψιστος</span> e em outros lugares»). Acerca de Jesus, <span class=\"greek\">ὡς</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">υἱοὺς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">προσηγόρευσεν</span> «como pai, chamou-nos (seus) filhos» 2 Cl 1:4 (cf. Ps.-Clem., Hom. 3, 19; <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστευόντων</span> <span class=\"greek\">ὑπάρχει</span> Did., Gen. 106, 6.—<span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. [= «fundador»] <span class=\"greek\">τῆς</span> <span class=\"greek\">τοιαύτης</span> <span class=\"greek\">διδασκαλίας</span> Orig., C. Cels. 2, 44, 32).<br><br>ⓑ Em sentido negativo, acerca do diabo (sobre a tradição patrística, veja Lampe s.v. <span class=\"greek\">πατήρ</span> D).<br><br><span class=\"greek\">α</span>. Como pai de um grupo de judeus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:44ab</a>, como juízo acerca do pecado de se opor ao propósito de Deus em Jesus, não acerca da pessoa (cf. descrições dos dissidentes em Qumran, especialmente 1QS e 1QH, com ênfase no aspecto do engano).<br><br><span class=\"greek\">β</span>. Como pai da mentira (Celsus 2, 47 como <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span>) v. 44c (sobre <span class=\"greek\">πατήρ</span> no sentido de «originador», cf. Caecil. Calact., Fgm. 127 <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">λόγου</span> = «o autor do livro»). Acerca da opinião de que em 44a e c poderia haver uma afirmação sobre o pai do diabo, veja Hdb.3 ad loc. (NDahl, Festschrift EHaenchen ’64, 70–84 [Caim]).—LDürr, Geistige Vaterrschaft in: Festschrift Herwegen ’38, 1–30.<br><br>④ Título de tratamento respeitoso, pai.<br><br>ⓐ Como título honorífico (Diod S 21, 12, 2; 5; Ps.-Callisth. 1, 14, 2 <span class=\"greek\">πάτερ</span>; 4 Km 2:12; 6:21; 13:14; Test Abr B 2 p. 106, 3 [Stone p. 60] <span class=\"greek\">καλὲ</span> <span class=\"greek\">πάτερ</span>; Jos., Ant. 12, 148; 13, 127; Just., D. 3, 7. Também PGen 52, 1; 5 <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">Ἀμινναίῳ</span> <span class=\"greek\">Ἀλύπιος</span>; UPZ 65, 3 [154 a.C.]; 70, 2; BGU 164, 2; POxy 1296, 15; 18; 1592, 3; 5; 1665, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:9a</a>; especificamente no tratamento dirigido aos membros do Sinédrio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:2a</a>; cf. 22:1 (acerca de Jó, em TestJob 53:3 <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀρφανῶν</span>).<br><br>ⓑ Como designação dos membros masculinos mais velhos de uma igreja (como forma respeitosa de tratamento por jovens dirigida aos mais velhos, Hom. e outros. Veja também a.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:13</a>, 14b.<br><br>⑤ Pessoas falecidas e reverenciadas com as quais alguém compartilha crenças ou tradições, pais, ancestrais.<br><br>ⓐ Geração (ou gerações) de cristãos falecidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>; 1 Cl 23:3=2 Cl 11:2 (dito apócrifo, ao menos assim interpretado pelos escritores cristãos). Também se poderia tratar de cristãos de uma geração anterior em 1 Cl 30:7; 60:4; 62:2; 2 Cl 19:4. Contudo, é possível que esses textos se refiram a:<br><br>ⓑ Heróis religiosos ilustres do AT, que são «antepassados» inclusive para cristãos gentios, reconhecidos como israelitas (Just., D. 101, 1). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:1</a>, Paulo denomina a geração de israelitas do deserto <span class=\"greek\">οἱ</span> <span class=\"greek\">πατέρες</span> <span class=\"greek\">ἡμῶν</span> («os filósofos» de tempos passados também recebem tal designação em Cleopatra 114f). Igualmente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:12b</a> Abraão é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἡμῶν</span> (a esse respeito, veja c abaixo). Também se faz referência a ele em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:21</a>; 1 Cl 31:2; de maneira semelhante, ao patriarca Jacó em 4:8.<br><br>ⓒ A «paternidade» também pode consistir no fato de que aquele chamado «pai» é protótipo de um grupo ou fundador de uma classe de pessoas (cf. Pla., Menex. 240e <span class=\"greek\">οὐ</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">σωμάτων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἡμετέρων</span> <span class=\"greek\">πατέρας</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλευθερίας</span>; 1 Macc 2:54). Abraão, que, ainda incircunciso, recebeu a promessa por causa de sua fé e depois recebeu a circuncisão como selo dela, tornou-se assim <span class=\"greek\">πατὴρ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πιστευόντων</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἀκροβυστίας</span> «pai de todos os que creem, embora incircuncisos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:11</a>, e também <span class=\"greek\">πατὴρ</span> <span class=\"greek\">περιτομῆς</span> «pai dos circuncisos» v. 12a, na medida em que eles não são apenas fisicamente circuncidados, mas também se assemelham ao patriarca quanto à fé. Cf. 4:16, 17 (Gen 17:5).<br><br>⑥ Divindade suprema, responsável pela origem e pelo cuidado de tudo o que existe, Pai, Genitor (Just., A II, 6, 2 <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κτίστης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δεσπότης</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀνόματά</span> <span class=\"greek\">ἐστιν</span>, <span class=\"greek\">ἀλλ</span>’ … <span class=\"greek\">προσφήσεις</span> «os termos pai, deus, criador, senhor e soberano não são nomes, mas … formas de tratamento [em reconhecimento de benefícios e ações]»).<br><br>ⓐ Como originador e governante (Pind., O. 2, 17 <span class=\"greek\">Χρόνος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">π</span>.; Pla., Tim. 28c; 37c; Stoa: Epict. 1, 3, 1; Diog. L. 7, 147; Maximus Tyr. 2, 10a; Galen XIX p. 179 K. <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">θεοῖς</span>; Job 38:28; Mal 2:10; Philo, Spec. Leg. 1, 96 <span class=\"greek\">τῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">πατρί</span>; 2, 6 <span class=\"greek\">τὸν</span> <span class=\"greek\">ποιητὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>, Ebr. 30; 81, Virt. 34; 64; 179; 214; Jos., Ant. 1, 20 <span class=\"greek\">πάντων</span> <span class=\"greek\">πατήρ</span>; 230; 2, 152; 7, 380 <span class=\"greek\">πατέρα</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">γένεσιν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>; Herm. Wr. 1, 21 <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὅλων</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πατήρ</span>; 30 e outros, também p. 476, 23 Sc. <span class=\"greek\">δεσπότης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιητής</span>; PGM 4, 1170; 1182; Just., A I, 45, 1 <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">θεός</span>; D. 95, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>; Ath. 27, 2; Iren.; Orig., C. Cels. 1, 46, 34; Hippolyt.; <span class=\"greek\">π</span>. <span class=\"greek\">δὲ</span> <span class=\"greek\">δὶα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> Theoph. Ant. 1, 4 [p. 64, 8]) <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φώτων</span> «Pai dos corpos celestes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:17</a> (cf. ApcMos 36, variante textual [MCeriani, Monumenta Sacra et Profana V/1, 1868] <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φωτὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φώτων</span>; 38).<br><br>ⓑ Como <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πνευμάτων</span> «Pai dos espíritos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:9b</a> (cf. Num 16:22; 27:16 e, em En, a expressão fixa «Senhor dos espíritos»).—Veja PKatz, Philo’s Bible ’50, p. 33, 1.<br><br>ⓒ Como Pai da humanidade (desde Hom., <span class=\"greek\">Ζεύς</span> é chamado <span class=\"greek\">πατήρ</span> ou <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἀνδρῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τε</span>; Diod S 5, 72, 2 <span class=\"greek\">πατέρα</span> <span class=\"greek\">δὲ</span> [<span class=\"greek\">αὐτὸν</span> <span class=\"greek\">προσαγορευθῆναι</span>] <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φροντίδα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὔνοιαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἅπαντας</span>, <span class=\"greek\">ἔτι</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δοκεῖν</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">ἀρχηγὸν</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> = «[Zeus é chamado] pai por causa de seu cuidado e benevolência para com toda a humanidade e, ainda, porque é considerado originador da raça humana»; cf. 3, 61, 4; 5, 56, 4; Dio Chrys. 36 [53], 12, Zeus como <span class=\"greek\">π</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, não apenas por sua posição de governante, mas também por seu amor e cuidado [<span class=\"greek\">ἀγαπῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">προνοῶν</span>]. Cf. Plut., Mor. 167d; Jos., Ant. 4, 262 <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">γένους</span>. No AT, Deus é chamado «Pai» principalmente para indicar relação de cuidado com a nação israelita como um todo ou com o rei como personificação dessa nação. Apenas em autores tardios Deus é chamado Pai do israelita piedoso como indivíduo: Sir 23:1, 4; Tob 13:4; Wsd 2:16; 14:3; 3 Macc 5:7.—Bousset, Rel.3 377ff; EBurton, ICC Gal 1921, 384–92; RGyllenberg, Gott d. Vater im AT u. in d. Predigt Jesu: Studia Orient. I 1925, 51–60; JLeipoldt, D. Gotteserlebnis Jesu 1927; AWilliams, ‘My Father’ in Jewish Thought of the First Century: JTS 31, 1930, 42–47; TManson, The Teaching of Jesus, ’55, 89–115; HMontefiore, NTS 3, ’56/57, 31–46 [sinóticos]; BIersel, ‘D. Sohn’ in den synopt. Ev., ’61, 92–116).<br><br><span class=\"greek\">α</span>. Conforme a fala de Jesus, <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:4</a>, 6b, 18b. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:15</a>; 10:20, 29; 23:9b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:36</a>; 12:30, 32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:17c</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">αὐτῶν</span> (= <span class=\"greek\">τῶν</span> <span class=\"greek\">δικαίων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:43</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> (<span class=\"greek\">τοῖς</span>) <span class=\"greek\">οὐρανοῖς</span> (a sinagoga também falava de Deus como «Pai no Céu»; Bousset, Rel.3 378) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:16</a>, 45; 6:1; 7:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:25</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐράνιος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:48</a>; 6:14, 26, 32. Cf. 23:9b. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:13</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρυπτῷ</span> (ou <span class=\"greek\">κρυφαίῳ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:6a</a>, 18a.—Para o evangelista, as palavras <span class=\"greek\">πάτερ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οὐρανοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:9</a> referem-se apenas à relação entre Deus e os seres humanos, embora Jesus talvez se incluísse nesta parte da oração. O mesmo vale para <span class=\"greek\">πάτερ</span> <span class=\"greek\">ἁγιασθήτω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">σου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:2</a> (quanto à invocação na oração, cf. Simonides, Fgm. 13, 20 <span class=\"greek\">Ζεῦ</span> <span class=\"greek\">πάτερ</span>).—ELohmeyer, D. Vaterunser erkl. ’46 (tradução inglesa JBowden, ’65); TManson, The Sayings of Jesus, ’54, 165–71; EGraesser, Das Problem der Parusieverzögerung in den synopt. Ev. usw., Beih. ZNW 22, ’57, 95–113; AHamman, La Prière I, Le NT, ’59, 94–134; JJeremias, Das Vaterunser im Lichte der neueren Forschung, ’62 (tradução inglesa The Lord’s Prayer, JReumann, ’64); WMarchel, Abba, Père! La Prière ’63; também bibliografia em JCharlesworth, ed., The Lord’s Prayer and Other Prayer Texts fr. the Greco-Roman Era ’94, 186–201.<br><br><span class=\"greek\">β</span>. Segundo os cristãos (Sextus 59=222; 225, Deus como <span class=\"greek\">π</span>. dos piedosos. O servo de Sarapis dirige-se a Deus dessa maneira: Sb 1046; 3731, 7), nas introduções das cartas, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἡμῶν</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:3</a>, cf. v. 4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:2</a>; Phlm 3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:2</a> (variante textual sem <span class=\"greek\">ἡμῶν</span>); sem <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:2</a> (variante textual com <span class=\"greek\">ἡμῶν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:2</a>; Tit 1:4; 2J 3a (aqui o v. 3b mostra claramente que não se trata de «nosso» Pai, mas do Pai de Jesus Cristo).—<span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἡμῶν</span> também em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>; 3:11, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:16</a>; D 8:2; 9:2f. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπιεικῆ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὔσπλαγχνον</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἡμῶν</span> 1 Cl 29:1. Igualmente, o Pai dos crentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:15</a> (com <span class=\"greek\">αββα</span>, veja JBarr, Abba Isn’t Daddy: JTS 39, ’88, 28–47; veja também JFitzmyer, Ro [AB] ad loc.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3b</a> (<span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκτιρμῶν</span>; veja <span class=\"greek\">οἰκτιρμός</span>); 6:18 (cf. 2 Km 7:14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:6</a> (<span class=\"greek\">πατὴρ</span> <span class=\"greek\">πάντων</span>, como Herm. Wr. 5, 10); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:17</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκτίρμων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὐεργετικὸς</span> <span class=\"greek\">πατήρ</span> 1 Cl 23:1. Cf. 8:3 (talvez de livro apócrifo desconhecido). <span class=\"greek\">πάτερ</span> <span class=\"greek\">ἅγιε</span> D 10:2 (cf. 8:2; 9:2f).<br><br><span class=\"greek\">γ</span>. Segundo os judeus, <span class=\"greek\">ἕνα</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἔχομεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> «temos um só Pai, Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:41b</a>. Cf. v. 42.<br><br>ⓓ Como Pai de Jesus Cristo.<br><br><span class=\"greek\">α</span>. No testemunho de Jesus acerca de si mesmo, <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27a</a>; 20:23; 25:34; 26:29, 39, 42, 53; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:49</a> (veja <span class=\"greek\">ὁ</span> 2g e Goodsp., Probs. 81–83); 10:22a; 22:29; 24:49; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>; 5:17, 43; 6:40 e frequentemente em J; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:28</a>; 3:5, 21. <span class=\"greek\">ἡ</span> <span class=\"greek\">βασιλεία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span> 2 Cl 12:6, num dito apócrifo de Jesus. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> (<span class=\"greek\">τοῖς</span>) <span class=\"greek\">οὐρανοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:21</a>; 10:32, 33; 12:50; 16:17; 18:10, 19. <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐράνιος</span> 15:13; 18:35 (Just., A I, 15, 8). Jesus chama-se o Homem (Filho do Homem), que virá <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">δόξῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">αὐτοῦ</span> «na glória de seu Pai» 16:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:38</a>. Absolutamente, <span class=\"greek\">ὁ</span> <span class=\"greek\">πατήρ</span>, <span class=\"greek\">πάτερ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:36</a> (veja GSchelbert, FZPhT 40, ’93, 259–81; resposta de ERuckstuhl, ibid. 41, ’94, 515–25; réplica de Schelbert, ibid. 526–31); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21ab</a>; 22:42; 23:34, 46 (todos vocativos); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:21</a>, 23ab; 5:36ab, 37, 45; 6:27, 37, 45, 46a, 65 e frequentemente em J. Pai e Filho aparecem lado a lado ou em contraste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:27bc</a>; 24:36; 28:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:22bc</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:19</a>–23, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:3</a>; 2:22–24; 2J 9; B 12:8. WLofthouse, Vater u. Sohn im J: ThBl 11, ’32, 290–300.<br><br><span class=\"greek\">β</span>. Na confissão dos cristãos, <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>. <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:31</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:5</a> (2 Km 7:14); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:6</a>; 1 Cl 7:4; IEph 2:1; ITr ins 12:2; MPol 14:1; AcPl Ha 2, 33; 6, 34; AcPlCor 2:7 (cf. Just., D. 30, 3; 129, 1 e outros).<br><br>ⓔ Frequentemente Deus é chamado simplesmente (<span class=\"greek\">ὁ</span>) <span class=\"greek\">πατήρ</span> «(o) Pai» (por exemplo, TestJob 33:9; veja DRahnenführer, ZNW 62, ’71, 77; ApcMos 35 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀοράτου</span> <span class=\"greek\">πατρός</span>; Just., D. 76, 3 e outros. Sobre a presença ou ausência do artigo, veja B-D-F §257, 3; Rob. 795) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:18</a>; 3:14; 5:20; 6:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:2</a>; 2:1, 15; 3:1; B 14:6; Hv 3, 9, 10; IEph 3:2; 4:2; IMg 13:2; ITr 12:2; 13:3; IRo 2:2; 3:3; 7:2; 8:2; IPhld 9:1; ISm 3:3; 7:1; 8:1; D 1:5; Dg 12:9; 13:1; AcPlCor 2:5, 19; MPol 22:3; EpilMosq 5. <span class=\"greek\">θεὸς</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:1</a> (quanto à formulação <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">πατήρ</span>, cf. Diod S 4, 11, 1: Héracles devia obedecer <span class=\"greek\">τῷ</span> <span class=\"greek\">Διὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατρί</span>; Oenomaus em Eus., PE 5, 35, 3 <span class=\"greek\">Λοξίας</span> [= Apolo] <span class=\"greek\">καὶ</span> <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">πατήρ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:1</a>, 2, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>; Jd 1; IEph ins a; ISm ins; IPol ins; MPol ins. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:17</a>, variante textual; MPol 22:1; <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:9</a>.—Atribuem-se também qualificações a <span class=\"greek\">πατήρ</span> (Zoroastro segundo Philo Bybl.: 790 Fgm. 4, 52 Jac. [em Eus., PE 1, 10, 52], Deus é <span class=\"greek\">π</span>. <span class=\"greek\">εὐνομίας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαιοσύνης</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> «o Pai da glória» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:17</a>. <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ὕψιστος</span> IRo ins. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">παντοκράτωρ</span> MPol 19:2.—B. 103. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πάτμος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome geográfico masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πάτμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Thu. 3, 33, 3; Strabo 10, 5, 13; Pliny, HN 4, 23; CIG 2261; 2262; SIG 1068, 2), Patmos, pequena ilha rochosa do mar Egeu, célebre pela tradição de que João recebeu sua «revelação» ali, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:9</a>. Seu exílio em Patmos (cf. Artem. 5, 21 <span class=\"greek\">εἰς</span> <span class=\"greek\">νῆσον</span> <span class=\"greek\">κατεδικάσθη</span>) é tradição antiga: Clem. Alex., Quis Div. Salv. 42; Origen, In Matth. vol. 16, 6 p. 486, 10 Kl.; Eus., HE 3, 18, 1–3; Tertullian, De Praescr. Haer. 36. Veja JFrings, D. Patmosexil des Ap. Joh. nach Apk 1:9: TQ 104, 1923, 23–30.—Pauly-W. XVIII 2174–91; Kl. Pauly IV 549; BHHW III 1400f; PECS 681.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0276-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πατραλῴας</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πατραλῴας</span>: veja <span class=\"greek\">πατρολῴας</span>.</p></section></article>"};
